INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-02', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 2', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 2);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 1, 'effective', 'hiệu quả; có hiệu lực', 'adjective', '[{"en":"Walking every day is an effective way to stay healthy.","vi":"Đi bộ mỗi ngày là một cách hiệu quả để giữ sức khỏe."},{"en":"This medicine is very effective against headaches.","vi":"Thuốc này trị đau đầu rất hiệu quả."},{"en":"The new rules will become effective next month.","vi":"Các quy định mới sẽ có hiệu lực từ tháng sau."}]', '[{"phrase":"effective way"},{"phrase":"highly effective"},{"phrase":"become effective"}]', NULL, '/ɪˈfektɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eff/effec/effective__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 2, 'correct', 'đúng; chính xác', 'adjective', '[{"en":"Is this the correct address for the hotel?","vi":"Đây có phải là địa chỉ đúng của khách sạn không?"},{"en":"You''re correct that the meeting starts at nine.","vi":"Bạn nói đúng, cuộc họp bắt đầu lúc chín giờ."},{"en":"Please check that all your answers are correct before you finish.","vi":"Hãy kiểm tra xem mọi câu trả lời đã đúng chưa trước khi làm xong."}]', '[{"phrase":"correct answer"},{"phrase":"absolutely correct"},{"phrase":"the correct way"}]', 'cũng là động từ: sửa (correct a mistake)', '/kəˈrekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/corre/correct__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 3, 'medical', '(thuộc) y tế; y khoa', 'adjective', '[{"en":"The injured driver needed medical help right away.","vi":"Người lái xe bị thương cần được hỗ trợ y tế ngay lập tức."},{"en":"My brother is in his second year of medical school.","vi":"Anh trai tôi đang học năm thứ hai trường y."},{"en":"All new employees must have a medical check-up before starting work.","vi":"Tất cả nhân viên mới phải khám sức khỏe trước khi bắt đầu làm việc."}]', '[{"phrase":"medical care"},{"phrase":"medical school"},{"phrase":"medical treatment"}]', NULL, '/ˈmedɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/med/medic/medical__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 4, 'admit', 'thừa nhận; cho vào, nhận vào (bệnh viện, trường)', 'verb', '[{"en":"He finally admitted that he had made a mistake.","vi":"Cuối cùng anh ấy cũng thừa nhận rằng mình đã mắc lỗi."},{"en":"I have to admit I was a little nervous.","vi":"Phải thừa nhận là tôi đã hơi lo lắng."},{"en":"She was admitted to the hospital with a high fever.","vi":"Cô ấy phải nhập viện vì sốt cao."}]', '[{"phrase":"admit a mistake"},{"phrase":"admit defeat"},{"phrase":"admitted to the hospital"}]', 'admit – admitted – admitted', '/ədˈmɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adm/admit/admit__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 5, 'beat', 'đánh bại, thắng; đập (tim); đánh (trứng)', 'verb', '[{"en":"Our school team beat the best team in the city.","vi":"Đội của trường tôi đã đánh bại đội mạnh nhất thành phố."},{"en":"My heart was beating fast before the exam.","vi":"Tim tôi đập nhanh trước giờ thi."},{"en":"Beat the eggs and sugar together for two minutes.","vi":"Đánh trứng với đường trong hai phút."}]', '[{"phrase":"beat eggs"},{"phrase":"beat the traffic"},{"phrase":"easily beat"}]', 'beat – beat – beaten', '/biːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bea/beat_/beat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 6, 'telephone', 'điện thoại', 'noun', '[{"en":"Please write your name and telephone number on the form.","vi":"Vui lòng ghi tên và số điện thoại của bạn vào mẫu đơn."},{"en":"The telephone rang just as we sat down to dinner.","vi":"Điện thoại reo đúng lúc chúng tôi ngồi xuống ăn tối."},{"en":"Most customers contact us by telephone or email.","vi":"Hầu hết khách hàng liên hệ với chúng tôi qua điện thoại hoặc email."}]', '[{"phrase":"telephone number"},{"phrase":"by telephone"},{"phrase":"telephone call"},{"phrase":"answer the telephone"}]', NULL, '/ˈtelɪfəʊn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tel/telep/telephone__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 7, 'copy', 'bản sao; bản, cuốn (sách, báo)', 'noun', '[{"en":"Can you make a copy of this letter for me?","vi":"Bạn có thể sao giúp tôi một bản của lá thư này không?"},{"en":"Keep a copy of your passport in a safe place.","vi":"Hãy giữ một bản sao hộ chiếu ở nơi an toàn."},{"en":"The library has three copies of that book.","vi":"Thư viện có ba cuốn sách đó."}]', '[{"phrase":"make a copy"},{"phrase":"keep a copy"},{"phrase":"hard copy"}]', 'cũng là động từ: sao chép, chép (copy a file)', '/ˈkɑːpi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cop/copy_/copy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 8, 'committee', 'ủy ban; ban', 'noun', '[{"en":"She was asked to join the planning committee for the festival.","vi":"Cô ấy được mời tham gia ban kế hoạch của lễ hội."},{"en":"The committee meets once a month to discuss new ideas.","vi":"Ủy ban họp mỗi tháng một lần để thảo luận các ý tưởng mới."},{"en":"A small committee will decide who wins the prize.","vi":"Một ban nhỏ sẽ quyết định ai giành giải thưởng."}]', '[{"phrase":"committee meeting"},{"phrase":"join a committee"},{"phrase":"planning committee"},{"phrase":"committee member"}]', 'chính tả: 2 m, 2 t, 2 e', '/kəˈmɪti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commi/committee__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 9, 'aware', 'biết; nhận thức được', 'adjective', '[{"en":"Are you aware that the store closes early today?","vi":"Bạn có biết hôm nay cửa hàng đóng cửa sớm không?"},{"en":"I wasn''t aware of the problem until my boss told me.","vi":"Tôi không biết về vấn đề này cho đến khi sếp nói với tôi."},{"en":"Parents should be aware of what their children watch online.","vi":"Cha mẹ nên biết con mình xem gì trên mạng."}]', '[{"phrase":"aware of"},{"phrase":"become aware"},{"phrase":"fully aware"},{"phrase":"well aware"}]', 'aware of sth / aware that…', '/əˈwer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/awa/aware/aware__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 10, 'advice', 'lời khuyên', 'noun', '[{"en":"Can I ask you for some advice about my job?","vi":"Tôi có thể xin bạn vài lời khuyên về công việc của tôi không?"},{"en":"My grandmother always gives me good advice.","vi":"Bà tôi luôn cho tôi những lời khuyên hay."},{"en":"You should follow the doctor''s advice and rest for a few days.","vi":"Bạn nên làm theo lời khuyên của bác sĩ và nghỉ ngơi vài ngày."}]', '[{"phrase":"give advice"},{"phrase":"ask for advice"},{"phrase":"follow advice"},{"phrase":"piece of advice"}]', 'không đếm được: a piece of advice · advice (n) ≠ advise (v)', '/ədˈvaɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/advic/advice__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 11, 'handle', 'xử lý, giải quyết; cầm, cầm nắm', 'verb', '[{"en":"She handled the angry customer very calmly.","vi":"Cô ấy xử lý vị khách đang tức giận rất bình tĩnh."},{"en":"I don''t know if I can handle all this work alone.","vi":"Tôi không biết liệu mình có thể một mình lo hết chỗ việc này không."},{"en":"Please handle these glasses carefully because they break easily.","vi":"Vui lòng cầm những chiếc ly này cẩn thận vì chúng rất dễ vỡ."}]', '[{"phrase":"handle a situation"},{"phrase":"handle a problem"},{"phrase":"handle with care"}]', 'cũng là danh từ: tay cầm, tay nắm', '/ˈhændl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/han/handl/handle__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 12, 'glass', 'ly, cốc; kính, thủy tinh', 'noun', '[{"en":"Could I have a glass of water, please?","vi":"Cho tôi xin một cốc nước được không?"},{"en":"The table top is made of glass, so be careful.","vi":"Mặt bàn làm bằng kính nên hãy cẩn thận."},{"en":"He broke a glass while he was washing the dishes.","vi":"Anh ấy làm vỡ một cái ly khi đang rửa bát."}]', '[{"phrase":"a glass of water"},{"phrase":"broken glass"},{"phrase":"wine glass"},{"phrase":"glass door"}]', 'glasses (số nhiều) còn có nghĩa là kính đeo mắt', '/ɡlæs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gla/glass/glass__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 13, 'trial', 'phiên tòa, sự xét xử; sự thử nghiệm, dùng thử', 'noun', '[{"en":"The trial is expected to last about two weeks.","vi":"Phiên tòa dự kiến kéo dài khoảng hai tuần."},{"en":"The man went on trial for stealing a car.","vi":"Người đàn ông bị đưa ra xét xử vì tội trộm xe hơi."},{"en":"The app offers a free trial for the first month.","vi":"Ứng dụng này cho dùng thử miễn phí trong tháng đầu tiên."}]', '[{"phrase":"free trial"},{"phrase":"on trial"},{"phrase":"clinical trial"},{"phrase":"trial period"}]', NULL, '/ˈtraɪəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tri/trial/trial__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 14, 'stress', 'căng thẳng; áp lực', 'noun', '[{"en":"Too much stress can make it hard to sleep.","vi":"Căng thẳng quá mức có thể khiến bạn khó ngủ."},{"en":"She has been under a lot of stress at work lately.","vi":"Dạo này cô ấy chịu nhiều áp lực trong công việc."},{"en":"Going for a walk is a good way to reduce stress.","vi":"Đi dạo là một cách tốt để giảm căng thẳng."}]', '[{"phrase":"under stress"},{"phrase":"reduce stress"},{"phrase":"stress levels"}]', 'cũng là động từ: nhấn mạnh (stress the importance of…)', '/stres/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stres/stress__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 15, 'radio', 'đài, radio', 'noun', '[{"en":"I heard the news on the radio this morning.","vi":"Tôi nghe tin đó trên đài sáng nay."},{"en":"My dad always listens to the radio while he drives.","vi":"Bố tôi luôn nghe đài khi lái xe."},{"en":"Can you turn the radio down a little?","vi":"Bạn vặn nhỏ đài một chút được không?"}]', '[{"phrase":"listen to the radio"},{"phrase":"on the radio"},{"phrase":"radio station"},{"phrase":"turn on the radio"}]', NULL, '/ˈreɪdiəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rad/radio/radio__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 16, 'administration', 'công tác hành chính, quản lý; ban quản lý', 'noun', '[{"en":"She has worked in hospital administration for ten years.","vi":"Cô ấy đã làm công tác hành chính ở bệnh viện được mười năm."},{"en":"Teachers spend too much time on administration instead of teaching.","vi":"Giáo viên dành quá nhiều thời gian cho việc hành chính thay vì giảng dạy."},{"en":"The school administration decided to cancel classes because of the storm.","vi":"Ban giám hiệu nhà trường quyết định cho học sinh nghỉ học vì bão."}]', '[{"phrase":"business administration"},{"phrase":"school administration"},{"phrase":"administration costs"}]', NULL, '/ədˌmɪnɪˈstreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adm/admin/administration__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 17, 'complex', 'phức tạp', 'adjective', '[{"en":"The instructions were too complex for most people to follow.","vi":"Hướng dẫn quá phức tạp nên hầu hết mọi người không làm theo được."},{"en":"Learning a language is a long and complex process.","vi":"Học một ngôn ngữ là một quá trình lâu dài và phức tạp."},{"en":"This is a complex problem with no easy answer.","vi":"Đây là một vấn đề phức tạp, không có lời giải dễ dàng."}]', '[{"phrase":"complex issue"},{"phrase":"complex process"},{"phrase":"highly complex"},{"phrase":"complex system"}]', 'cũng là danh từ: khu phức hợp (sports complex)', '/kəmˈpleks/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complex__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 18, 'text', 'văn bản, chữ; tin nhắn', 'noun', '[{"en":"Send me a text when you get home.","vi":"Nhắn tin cho tôi khi bạn về đến nhà nhé."},{"en":"Read the text carefully and answer the questions below.","vi":"Đọc kỹ văn bản và trả lời các câu hỏi bên dưới."},{"en":"You can make the text bigger so it''s easier to read.","vi":"Bạn có thể phóng to chữ để dễ đọc hơn."}]', '[{"phrase":"text message"},{"phrase":"send a text"},{"phrase":"read the text"}]', 'cũng là động từ: nhắn tin (text me)', '/tekst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tex/text_/text__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 19, 'context', 'ngữ cảnh; bối cảnh', 'noun', '[{"en":"Try to guess the meaning of the word from the context.","vi":"Hãy thử đoán nghĩa của từ dựa vào ngữ cảnh."},{"en":"His words were taken out of context.","vi":"Lời anh ấy nói đã bị tách khỏi ngữ cảnh."},{"en":"You need some historical context to understand this story.","vi":"Bạn cần biết chút bối cảnh lịch sử để hiểu câu chuyện này."}]', '[{"phrase":"in context"},{"phrase":"out of context"},{"phrase":"historical context"},{"phrase":"in this context"}]', NULL, '/ˈkɑːntekst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontext__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 20, 'ride', 'đi (xe đạp, xe máy, tàu xe); cưỡi (ngựa)', 'verb', '[{"en":"My daughter learned to ride a bike when she was five.","vi":"Con gái tôi học đi xe đạp khi lên năm tuổi."},{"en":"We rode the train all the way to the coast.","vi":"Chúng tôi đi tàu suốt đến tận vùng biển."},{"en":"Have you ever ridden a horse on the beach?","vi":"Bạn đã bao giờ cưỡi ngựa trên bãi biển chưa?"}]', '[{"phrase":"ride a bike"},{"phrase":"ride a horse"},{"phrase":"ride a motorcycle"}]', 'ride – rode – ridden', '/raɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rid/ride_/ride__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 21, 'directly', 'trực tiếp; thẳng; ngay (đối diện)', 'adverb', '[{"en":"You can contact the manager directly by email.","vi":"Bạn có thể liên hệ trực tiếp với quản lý qua email."},{"en":"The hotel is directly opposite the train station.","vi":"Khách sạn nằm ngay đối diện ga tàu."},{"en":"Never look directly at the sun, even with sunglasses.","vi":"Đừng bao giờ nhìn thẳng vào mặt trời, kể cả khi đeo kính râm."}]', '[{"phrase":"directly involved"},{"phrase":"directly opposite"},{"phrase":"directly affect"}]', NULL, '/dəˈrektli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dir/direc/directly__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 22, 'heavy', 'nặng; (mưa, xe cộ) lớn, đông', 'adjective', '[{"en":"This box is too heavy for me to lift.","vi":"Cái hộp này quá nặng, tôi không nhấc nổi."},{"en":"We were late because of heavy traffic on the highway.","vi":"Chúng tôi bị muộn vì xe cộ đông đúc trên đường cao tốc."},{"en":"Heavy rain is expected across the region tomorrow.","vi":"Ngày mai dự báo sẽ có mưa lớn trên khắp khu vực."}]', '[{"phrase":"heavy rain"},{"phrase":"heavy traffic"},{"phrase":"heavy meal"}]', NULL, '/ˈhevi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/heavy/heavy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 23, 'remove', 'lấy đi, dọn đi; cởi, tháo; tẩy, loại bỏ', 'verb', '[{"en":"Please remove your shoes before entering the house.","vi":"Vui lòng cởi giày trước khi vào nhà."},{"en":"Can this cleaner remove coffee stains from a white shirt?","vi":"Loại nước tẩy này có tẩy được vết cà phê trên áo sơ mi trắng không?"},{"en":"The waiter removed our plates after we finished eating.","vi":"Người phục vụ dọn đĩa đi sau khi chúng tôi ăn xong."}]', '[{"phrase":"remove stains"},{"phrase":"remove from"},{"phrase":"completely remove"}]', NULL, '/rɪˈmuːv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remov/remove__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 24, 'conduct', 'tiến hành, thực hiện', 'verb', '[{"en":"The company conducted a survey of its customers last year.","vi":"Năm ngoái công ty đã tiến hành khảo sát khách hàng của mình."},{"en":"Scientists are conducting tests on the new medicine.","vi":"Các nhà khoa học đang tiến hành thử nghiệm loại thuốc mới."},{"en":"The interviews will be conducted in English.","vi":"Các buổi phỏng vấn sẽ được thực hiện bằng tiếng Anh."}]', '[{"phrase":"conduct a survey"},{"phrase":"conduct research"},{"phrase":"conduct an interview"},{"phrase":"conduct an experiment"}]', 'danh từ conduct (nhấn âm đầu): hạnh kiểm, cách cư xử', '/kənˈdʌkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcond/xconduct__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 25, 'equipment', 'thiết bị, dụng cụ', 'noun', '[{"en":"The gym has lots of modern equipment.","vi":"Phòng tập có rất nhiều thiết bị hiện đại."},{"en":"Don''t forget to bring your camping equipment.","vi":"Đừng quên mang theo dụng cụ cắm trại của bạn."},{"en":"All the office equipment was checked before the new staff arrived.","vi":"Toàn bộ thiết bị văn phòng đã được kiểm tra trước khi nhân viên mới đến."}]', '[{"phrase":"office equipment"},{"phrase":"sports equipment"},{"phrase":"piece of equipment"},{"phrase":"medical equipment"}]', 'không đếm được: a piece of equipment', '/ɪˈkwɪpmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equip/equipment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 26, 'otherwise', 'nếu không thì; ngoài ra thì; khác đi', 'adverb', '[{"en":"We should leave now; otherwise, we''ll miss the bus.","vi":"Chúng ta nên đi ngay, nếu không thì sẽ lỡ chuyến xe buýt."},{"en":"The soup was a bit salty, but otherwise the meal was great.","vi":"Món súp hơi mặn, nhưng ngoài ra thì bữa ăn rất ngon."},{"en":"Unless you tell me otherwise, I''ll meet you at six.","vi":"Nếu bạn không báo gì khác thì sáu giờ tôi sẽ gặp bạn."}]', '[{"phrase":"think otherwise"},{"phrase":"unless otherwise stated"},{"phrase":"say otherwise"}]', NULL, '/ˈʌðərwaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/oth/other/otherwise__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 27, 'title', 'tên, tiêu đề (sách, phim, bài hát); danh hiệu', 'noun', '[{"en":"What''s the title of the movie you watched last night?","vi":"Bộ phim bạn xem tối qua tên là gì?"},{"en":"I can''t remember the title of that song.","vi":"Tôi không nhớ tên bài hát đó."},{"en":"She won the national title for the second year in a row.","vi":"Cô ấy giành danh hiệu vô địch quốc gia năm thứ hai liên tiếp."}]', '[{"phrase":"job title"},{"phrase":"win the title"},{"phrase":"the title of"}]', NULL, '/ˈtaɪtl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tit/title/title__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 28, 'extra', 'thêm; phụ, dư', 'adjective', '[{"en":"Do you have an extra pen I could borrow?","vi":"Bạn có cây bút nào dư cho tôi mượn không?"},{"en":"The hotel charges an extra fee for breakfast.","vi":"Khách sạn tính thêm phí cho bữa sáng."},{"en":"I''m working extra hours this week to save money.","vi":"Tuần này tôi làm thêm giờ để tiết kiệm tiền."}]', '[{"phrase":"extra money"},{"phrase":"extra time"},{"phrase":"extra charge"},{"phrase":"extra hours"}]', NULL, '/ˈekstrə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/extra/extra__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 29, 'executive', 'giám đốc, người điều hành; ban lãnh đạo', 'noun', '[{"en":"She is a senior executive at a large bank.","vi":"Bà ấy là giám đốc cấp cao ở một ngân hàng lớn."},{"en":"The company''s executives met to discuss the new plan.","vi":"Ban lãnh đạo công ty đã họp để thảo luận kế hoạch mới."},{"en":"My uncle became the chief executive of a small software company.","vi":"Chú tôi trở thành giám đốc điều hành của một công ty phần mềm nhỏ."}]', '[{"phrase":"chief executive"},{"phrase":"senior executive"},{"phrase":"business executive"}]', NULL, '/ɪɡˈzekjətɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exe/execu/executive__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-02', 30, 'chair', 'ghế; chủ tọa, chủ tịch (cuộc họp, ban)', 'noun', '[{"en":"Please pull up a chair and join us.","vi":"Kéo ghế lại ngồi cùng chúng tôi nhé."},{"en":"This chair is so comfortable that I almost fell asleep.","vi":"Chiếc ghế này êm đến mức tôi suýt ngủ quên."},{"en":"Who is the chair of the parents'' committee this year?","vi":"Năm nay ai là chủ tịch ban phụ huynh?"}]', '[{"phrase":"pull up a chair"},{"phrase":"office chair"},{"phrase":"sit in a chair"}]', NULL, '/tʃer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chair/chair__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-05', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 5', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 5);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 1, 'apart', 'cách nhau; riêng ra; rời ra', 'adverb', '[{"en":"Our houses are only about two miles apart.","vi":"Nhà chúng tôi chỉ cách nhau khoảng hai dặm."},{"en":"The twins have never lived apart until this year.","vi":"Cặp song sinh chưa bao giờ sống xa nhau cho đến năm nay."},{"en":"My old bike is starting to fall apart.","vi":"Chiếc xe đạp cũ của tôi bắt đầu hỏng rời ra từng mảnh."}]', '[{"phrase":"fall apart"},{"phrase":"live apart"},{"phrase":"far apart"},{"phrase":"apart from"}]', 'apart from = ngoài ... ra; trừ ... ra', '/əˈpɑːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/apa/apart/apart__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 2, 'suit', 'bộ com-lê; hợp với; thuận tiện cho', 'noun', '[{"en":"He wore a dark suit to the job interview.","vi":"Anh ấy mặc một bộ com-lê tối màu đi phỏng vấn xin việc."},{"en":"That shade of blue really suits you, so you should wear it more.","vi":"Màu xanh đó thật sự rất hợp với bạn, bạn nên mặc nhiều hơn."},{"en":"Does Friday afternoon suit you for the meeting?","vi":"Chiều thứ Sáu có tiện cho bạn để họp không?"}]', '[{"phrase":"wear a suit"},{"phrase":"business suit"},{"phrase":"suit your needs"}]', NULL, '/suːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sui/suit_/suit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 3, 'federal', '(thuộc) liên bang', 'adjective', '[{"en":"The new road was built with federal money.","vi":"Con đường mới được xây bằng tiền của liên bang."},{"en":"Federal law requires all workers to be paid fairly.","vi":"Luật liên bang yêu cầu mọi người lao động phải được trả lương công bằng."},{"en":"She got a job with the federal government after college.","vi":"Cô ấy có việc làm ở chính phủ liên bang sau khi tốt nghiệp đại học."}]', '[{"phrase":"federal government"},{"phrase":"federal law"},{"phrase":"federal funding"}]', NULL, '/ˈfedərəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fed/feder/federal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 4, 'reveal', 'tiết lộ; để lộ ra', 'verb', '[{"en":"She finally revealed the secret to her best friend.","vi":"Cuối cùng cô ấy đã tiết lộ bí mật cho bạn thân."},{"en":"The study revealed that most students sleep too little.","vi":"Nghiên cứu cho thấy hầu hết sinh viên ngủ quá ít."},{"en":"When he smiled, he revealed a missing tooth.","vi":"Khi anh ấy cười, để lộ ra một chiếc răng bị mất."}]', '[{"phrase":"reveal a secret"},{"phrase":"reveal the truth"},{"phrase":"reveal details"}]', NULL, '/rɪˈviːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revea/reveal__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 5, 'percentage', 'tỷ lệ phần trăm', 'noun', '[{"en":"What percentage of your salary do you save each month?","vi":"Mỗi tháng bạn tiết kiệm bao nhiêu phần trăm lương?"},{"en":"A small percentage of people work from home every day.","vi":"Một tỷ lệ nhỏ người làm việc tại nhà mỗi ngày."},{"en":"The percentage of students passing the exam rose this year.","vi":"Tỷ lệ học sinh thi đỗ đã tăng trong năm nay."}]', '[{"phrase":"small percentage"},{"phrase":"high percentage"},{"phrase":"percentage of"}]', NULL, '/pərˈsentɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perce/percentage__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 6, 'peace', 'hòa bình; sự yên bình', 'noun', '[{"en":"Both countries have lived in peace for many years.","vi":"Hai nước đã sống trong hòa bình suốt nhiều năm."},{"en":"I just want some peace and quiet after work.","vi":"Tôi chỉ muốn được yên tĩnh một chút sau giờ làm."},{"en":"Walking by the lake gives me a sense of peace.","vi":"Đi dạo bên hồ mang lại cho tôi cảm giác yên bình."}]', '[{"phrase":"peace and quiet"},{"phrase":"live in peace"},{"phrase":"peace of mind"},{"phrase":"world peace"}]', 'không đếm được', '/piːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pea/peace/peace__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 7, 'status', 'địa vị; tình trạng', 'noun', '[{"en":"In some cultures, owning land gives you high social status.","vi":"Ở một số nền văn hóa, sở hữu đất đai mang lại địa vị xã hội cao."},{"en":"You can check the status of your order online.","vi":"Bạn có thể kiểm tra tình trạng đơn hàng trên mạng."},{"en":"Please fill in your name and marital status on the form.","vi":"Vui lòng điền tên và tình trạng hôn nhân của bạn vào mẫu đơn."}]', '[{"phrase":"social status"},{"phrase":"marital status"},{"phrase":"check the status"}]', NULL, '/ˈsteɪtəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/statu/status__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 8, 'crime', 'tội phạm; tội ác', 'noun', '[{"en":"Crime in our neighborhood has dropped over the last few years.","vi":"Tội phạm ở khu phố chúng tôi đã giảm trong vài năm qua."},{"en":"He was sent to prison for a crime he didn''t commit.","vi":"Anh ta bị bỏ tù vì một tội mà anh ta không phạm."},{"en":"The police are still looking for witnesses to the crime.","vi":"Cảnh sát vẫn đang tìm nhân chứng của vụ phạm tội."}]', '[{"phrase":"commit a crime"},{"phrase":"crime rate"},{"phrase":"serious crime"}]', NULL, '/kraɪm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cri/crime/crime__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 9, 'decline', 'giảm sút; từ chối', 'verb', '[{"en":"Sales of printed newspapers have declined sharply in recent years.","vi":"Doanh số báo in đã giảm mạnh trong những năm gần đây."},{"en":"His health began to decline after he turned eighty.","vi":"Sức khỏe của ông bắt đầu suy giảm sau khi ông bước sang tuổi tám mươi."},{"en":"She politely declined the invitation to the party.","vi":"Cô ấy lịch sự từ chối lời mời dự tiệc."}]', '[{"phrase":"decline sharply"},{"phrase":"decline an invitation"},{"phrase":"decline an offer"}]', NULL, '/dɪˈklaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decli/decline__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 10, 'decade', 'thập kỷ; mười năm', 'noun', '[{"en":"The city has changed a lot over the past decade.","vi":"Thành phố đã thay đổi rất nhiều trong mười năm qua."},{"en":"They have been friends for more than three decades.","vi":"Họ đã là bạn của nhau hơn ba mươi năm."},{"en":"Prices will probably keep rising for the next decade.","vi":"Giá cả có lẽ sẽ tiếp tục tăng trong thập kỷ tới."}]', '[{"phrase":"past decade"},{"phrase":"next decade"},{"phrase":"for decades"},{"phrase":"decades ago"}]', NULL, '/ˈdekeɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decad/decade__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 11, 'launch', 'ra mắt; phát động; phóng', 'verb', '[{"en":"The company will launch its new phone next month.","vi":"Công ty sẽ ra mắt điện thoại mới vào tháng sau."},{"en":"The school launched a campaign to reduce plastic waste.","vi":"Nhà trường đã phát động một chiến dịch giảm rác thải nhựa."},{"en":"The rocket was launched early on Sunday morning.","vi":"Tên lửa được phóng vào sáng sớm Chủ nhật."}]', '[{"phrase":"launch a product"},{"phrase":"launch a campaign"},{"phrase":"launch a rocket"}]', NULL, '/lɔːntʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lau/launc/launch__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 12, 'warn', 'cảnh báo; dặn trước', 'verb', '[{"en":"My mother warned me not to walk home alone at night.","vi":"Mẹ tôi đã dặn tôi không được đi bộ về nhà một mình vào ban đêm."},{"en":"Doctors warn that too much sugar can harm your teeth.","vi":"Các bác sĩ cảnh báo rằng quá nhiều đường có thể làm hại răng."},{"en":"I''m warning you, the roads are very icy this morning.","vi":"Tôi báo trước cho bạn nhé, sáng nay đường rất trơn vì băng."}]', '[{"phrase":"warn somebody about"},{"phrase":"warn somebody not to"},{"phrase":"strongly warn"}]', 'warn sb (not) to do sth; warn sb about/of sth', '/wɔːrn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/war/warn_/warn__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 13, 'consumer', 'người tiêu dùng', 'noun', '[{"en":"Consumers are spending less money on clothes this year.","vi":"Năm nay người tiêu dùng chi ít tiền hơn cho quần áo."},{"en":"The new law is meant to protect consumers from unsafe products.","vi":"Luật mới nhằm bảo vệ người tiêu dùng khỏi các sản phẩm không an toàn."},{"en":"Many consumers now prefer to shop online.","vi":"Nhiều người tiêu dùng hiện nay thích mua sắm trên mạng hơn."}]', '[{"phrase":"consumer goods"},{"phrase":"consumer spending"},{"phrase":"consumer protection"}]', NULL, '/kənˈsuːmər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsumer__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 14, 'favor', 'sự giúp đỡ; ân huệ; sự ủng hộ', 'noun', '[{"en":"Could you do me a favor and close the window?","vi":"Bạn giúp tôi đóng cửa sổ được không?"},{"en":"I owe you a favor for helping me move last week.","vi":"Tôi nợ bạn một lần vì tuần trước đã giúp tôi chuyển nhà."},{"en":"Most of the staff are in favor of the new schedule.","vi":"Phần lớn nhân viên ủng hộ lịch làm việc mới."}]', '[{"phrase":"do somebody a favor"},{"phrase":"ask a favor"},{"phrase":"owe somebody a favor"},{"phrase":"in favor of"}]', 'Mỹ: favor · Anh: favour', '/ˈfeɪvər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 15, 'dry', 'khô; khô ráo; hanh khô', 'adjective', '[{"en":"Make sure your hair is dry before you go outside.","vi":"Hãy chắc chắn tóc bạn đã khô trước khi ra ngoài."},{"en":"The weather has been hot and dry all week.","vi":"Thời tiết nóng và khô suốt cả tuần."},{"en":"Keep the medicine in a cool, dry place.","vi":"Hãy bảo quản thuốc ở nơi khô ráo, thoáng mát."}]', '[{"phrase":"dry skin"},{"phrase":"dry weather"},{"phrase":"keep dry"},{"phrase":"dry season"}]', NULL, '/draɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dry/dry__/dry__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 16, 'partner', 'bạn đời; đối tác; bạn cùng nhóm', 'noun', '[{"en":"She lives with her partner and their two dogs.","vi":"Cô ấy sống cùng bạn đời và hai con chó của họ."},{"en":"He became a partner in the law firm last year.","vi":"Năm ngoái anh ấy trở thành đối tác trong công ty luật."},{"en":"Find a partner and practice the dialogue together.","vi":"Hãy tìm một bạn cùng cặp và luyện đoạn hội thoại với nhau."}]', '[{"phrase":"business partner"},{"phrase":"long-term partner"},{"phrase":"trading partner"}]', NULL, '/ˈpɑːrtnər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/partn/partner__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 17, 'institution', 'tổ chức; cơ quan; viện', 'noun', '[{"en":"She works for a large financial institution in the city.","vi":"Cô ấy làm việc cho một tổ chức tài chính lớn trong thành phố."},{"en":"Our university is one of the oldest institutions in the country.","vi":"Trường đại học của chúng tôi là một trong những cơ sở lâu đời nhất cả nước."},{"en":"People are losing trust in public institutions.","vi":"Người dân đang mất lòng tin vào các cơ quan nhà nước."}]', '[{"phrase":"financial institution"},{"phrase":"educational institution"},{"phrase":"public institution"}]', NULL, '/ˌɪnstɪˈtuːʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insti/institution__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 18, 'spot', 'chỗ; điểm; vết đốm', 'noun', '[{"en":"We found a nice spot by the river for our picnic.","vi":"Chúng tôi tìm được một chỗ đẹp bên sông để đi dã ngoại."},{"en":"This beach is a popular spot for tourists.","vi":"Bãi biển này là một điểm đến được du khách ưa thích."},{"en":"There''s a small red spot on the collar of your white shirt.","vi":"Có một vết đốm đỏ nhỏ trên cổ áo sơ mi trắng của bạn."}]', '[{"phrase":"parking spot"},{"phrase":"popular spot"},{"phrase":"on the spot"}]', '(v) spot = phát hiện, nhận ra', '/spɑːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spo/spot_/spot__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 19, 'horse', 'con ngựa', 'noun', '[{"en":"My daughter learned to ride a horse last summer.","vi":"Con gái tôi đã học cưỡi ngựa vào mùa hè năm ngoái."},{"en":"The farmer keeps three horses and a few cows.","vi":"Người nông dân nuôi ba con ngựa và vài con bò."},{"en":"We took a horse ride along the beach at sunset.","vi":"Chúng tôi cưỡi ngựa dọc bãi biển lúc hoàng hôn."}]', '[{"phrase":"ride a horse"},{"phrase":"horse riding"},{"phrase":"horse race"}]', NULL, '/hɔːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hor/horse/horse__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 20, 'eventually', 'cuối cùng; rốt cuộc', 'adverb', '[{"en":"After two hours of waiting, the bus eventually arrived.","vi":"Sau hai tiếng chờ đợi, cuối cùng xe buýt cũng đến."},{"en":"Don''t worry, you''ll eventually get used to the new job.","vi":"Đừng lo, rồi bạn sẽ quen với công việc mới thôi."},{"en":"They eventually decided to sell the house and move abroad.","vi":"Rốt cuộc họ quyết định bán nhà và chuyển ra nước ngoài."}]', '[{"phrase":"eventually decide"},{"phrase":"eventually lead to"},{"phrase":"eventually become"}]', 'eventually ≠ actually (thực ra)', '/ɪˈventʃuəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/event/eventually__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 21, 'heat', 'hơi nóng; sức nóng; nhiệt', 'noun', '[{"en":"I can''t sleep well in this summer heat.","vi":"Tôi không thể ngủ ngon trong cái nóng mùa hè này."},{"en":"Cook the onions over low heat for ten minutes.","vi":"Xào hành trên lửa nhỏ trong mười phút."},{"en":"The heat from the fire kept us warm all night.","vi":"Hơi nóng từ đống lửa giữ ấm cho chúng tôi suốt đêm."}]', '[{"phrase":"intense heat"},{"phrase":"low heat"},{"phrase":"summer heat"},{"phrase":"heat wave"}]', 'không đếm được', '/hiːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/heat_/heat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 22, 'excite', 'làm phấn khích; kích thích', 'verb', '[{"en":"The idea of traveling to Japan really excites me.","vi":"Ý tưởng đi du lịch Nhật Bản thật sự khiến tôi phấn khích."},{"en":"Don''t excite the kids too much before bedtime.","vi":"Đừng làm bọn trẻ quá phấn khích trước giờ đi ngủ."},{"en":"The team''s new plan didn''t seem to excite anyone.","vi":"Kế hoạch mới của nhóm có vẻ không làm ai hứng thú."}]', '[{"phrase":"excite interest"},{"phrase":"excite the imagination"}]', 'excited (người thấy phấn khích) ≠ exciting (gây phấn khích)', '/ɪkˈsaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excit/excite__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 23, 'reader', 'người đọc; độc giả', 'noun', '[{"en":"My son has always been a keen reader.","vi":"Con trai tôi luôn là một người rất thích đọc sách."},{"en":"The magazine asked its readers to send in their photos.","vi":"Tạp chí đã mời độc giả gửi ảnh của họ về."},{"en":"The writer uses simple language so young readers can follow.","vi":"Nhà văn dùng ngôn ngữ đơn giản để độc giả nhỏ tuổi có thể theo dõi."}]', '[{"phrase":"keen reader"},{"phrase":"avid reader"},{"phrase":"young readers"}]', NULL, '/ˈriːdər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reade/reader__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 24, 'importance', 'tầm quan trọng', 'noun', '[{"en":"Teachers often talk about the importance of good sleep.","vi":"Giáo viên thường nói về tầm quan trọng của giấc ngủ ngon."},{"en":"This decision is of great importance to our company.","vi":"Quyết định này có tầm quan trọng lớn đối với công ty chúng tôi."},{"en":"My parents taught me the importance of saving money.","vi":"Bố mẹ dạy tôi về tầm quan trọng của việc tiết kiệm tiền."}]', '[{"phrase":"the importance of"},{"phrase":"great importance"},{"phrase":"stress the importance"}]', 'không đếm được', '/ɪmˈpɔːrtns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impor/importance__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 25, 'distance', 'khoảng cách; quãng đường', 'noun', '[{"en":"What''s the distance between Hanoi and Da Nang?","vi":"Khoảng cách giữa Hà Nội và Đà Nẵng là bao xa?"},{"en":"The station is within walking distance of our hotel.","vi":"Nhà ga nằm cách khách sạn của chúng tôi một quãng đi bộ."},{"en":"We could see the mountains in the distance.","vi":"Chúng tôi có thể nhìn thấy những ngọn núi ở phía xa."}]', '[{"phrase":"walking distance"},{"phrase":"long distance"},{"phrase":"in the distance"},{"phrase":"short distance"}]', NULL, '/ˈdɪstəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/dista/distance__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 26, 'guide', 'hướng dẫn viên; sách hướng dẫn; dẫn đường', 'noun', '[{"en":"Our guide showed us around the old town.","vi":"Hướng dẫn viên dẫn chúng tôi đi tham quan khu phố cổ."},{"en":"I bought a travel guide before my trip to Thailand.","vi":"Tôi đã mua một cuốn sách hướng dẫn du lịch trước chuyến đi Thái Lan."},{"en":"A local farmer guided us through the forest.","vi":"Một người nông dân địa phương dẫn đường cho chúng tôi qua khu rừng."}]', '[{"phrase":"tour guide"},{"phrase":"travel guide"},{"phrase":"user guide"}]', NULL, '/ɡaɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gui/guide/guide__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 27, 'grant', 'cấp; cho phép; khoản trợ cấp', 'verb', '[{"en":"The bank granted him a loan to start his business.","vi":"Ngân hàng đã cấp cho anh ấy một khoản vay để khởi nghiệp."},{"en":"Visitors are not granted access to this part of the building.","vi":"Khách không được phép vào khu vực này của tòa nhà."},{"en":"She received a government grant to study abroad.","vi":"Cô ấy nhận được một khoản trợ cấp của chính phủ để đi du học."}]', '[{"phrase":"grant permission"},{"phrase":"grant access"},{"phrase":"grant a loan"},{"phrase":"take for granted"}]', 'take sth for granted = coi là đương nhiên', '/ɡrænt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grant/grant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 28, 'taxi', 'xe tắc xi', 'noun', '[{"en":"It''s raining, so let''s take a taxi home.","vi":"Trời đang mưa, nên mình đi tắc xi về nhà nhé."},{"en":"Could you call a taxi for me, please?","vi":"Bạn gọi giúp tôi một chiếc tắc xi được không?"},{"en":"The taxi driver helped us carry our bags inside.","vi":"Bác tài xế tắc xi giúp chúng tôi mang hành lý vào trong."}]', '[{"phrase":"take a taxi"},{"phrase":"call a taxi"},{"phrase":"taxi driver"},{"phrase":"taxi rank"}]', NULL, '/ˈtæksi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tax/taxi_/taxi__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 29, 'feed', 'cho ăn; nuôi', 'verb', '[{"en":"Can you feed the cat while I''m away?","vi":"Bạn có thể cho mèo ăn trong lúc tôi đi vắng không?"},{"en":"She works two jobs to feed her family.","vi":"Cô ấy làm hai công việc để nuôi gia đình."},{"en":"We fed the ducks with bread at the park.","vi":"Chúng tôi cho vịt ăn bánh mì ở công viên."}]', '[{"phrase":"feed a family"},{"phrase":"feed the baby"},{"phrase":"feed the animals"}]', 'feed – fed – fed', '/fiːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fee/feed_/feed__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-05', 30, 'pain', 'cơn đau; nỗi đau', 'noun', '[{"en":"I''ve had a pain in my back since yesterday.","vi":"Tôi bị đau lưng từ hôm qua."},{"en":"Take this medicine if the pain gets worse.","vi":"Uống thuốc này nếu cơn đau nặng hơn."},{"en":"Nothing could ease the pain of losing her old dog.","vi":"Không gì có thể xoa dịu nỗi đau mất chú chó già của cô ấy."}]', '[{"phrase":"back pain"},{"phrase":"feel pain"},{"phrase":"chest pain"},{"phrase":"ease the pain"}]', NULL, '/peɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pai/pain_/pain__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-06', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 6', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 6);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 1, 'sector', 'lĩnh vực; khu vực (kinh tế)', 'noun', '[{"en":"She has worked in the public sector for over ten years.","vi":"Cô ấy đã làm việc trong khu vực công hơn mười năm."},{"en":"Jobs in the tech sector often pay very well.","vi":"Việc làm trong lĩnh vực công nghệ thường được trả lương rất cao."},{"en":"The private sector created thousands of new jobs last year.","vi":"Năm ngoái, khu vực tư nhân đã tạo ra hàng nghìn việc làm mới."}]', '[{"phrase":"public sector"},{"phrase":"private sector"},{"phrase":"service sector"},{"phrase":"financial sector"}]', NULL, '/ˈsektər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secto/sector__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 2, 'mistake', 'lỗi; sai lầm', 'noun', '[{"en":"I made a few mistakes in my English homework.","vi":"Tôi đã mắc vài lỗi trong bài tập tiếng Anh."},{"en":"Leaving that job was the biggest mistake of my life.","vi":"Rời bỏ công việc đó là sai lầm lớn nhất đời tôi."},{"en":"Sorry, I took your umbrella by mistake.","vi":"Xin lỗi, tôi cầm nhầm ô của bạn."}]', '[{"phrase":"make a mistake"},{"phrase":"big mistake"},{"phrase":"by mistake"},{"phrase":"learn from your mistakes"}]', 'make a mistake (không dùng do)', '/mɪˈsteɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mis/mista/mistake__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 3, 'ensure', 'đảm bảo', 'verb', '[{"en":"Please ensure that all windows are closed before you leave.","vi":"Vui lòng đảm bảo tất cả cửa sổ đã được đóng trước khi bạn rời đi."},{"en":"We check every order carefully to ensure it arrives safely.","vi":"Chúng tôi kiểm tra kỹ từng đơn hàng để đảm bảo hàng đến nơi an toàn."},{"en":"Regular exercise helps ensure that you stay healthy as you age.","vi":"Tập thể dục thường xuyên giúp đảm bảo bạn vẫn khỏe mạnh khi có tuổi."}]', '[{"phrase":"ensure that"},{"phrase":"help ensure"},{"phrase":"ensure safety"},{"phrase":"ensure quality"}]', 'ensure (đảm bảo) ≠ insure (mua bảo hiểm)', '/ɪnˈʃʊr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ens/ensur/ensure__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 4, 'satisfy', 'làm hài lòng; đáp ứng', 'verb', '[{"en":"It''s hard to satisfy every customer, but we always try.","vi":"Thật khó làm hài lòng mọi khách hàng, nhưng chúng tôi luôn cố gắng."},{"en":"Nothing I do ever seems to satisfy my boss.","vi":"Dường như chẳng việc gì tôi làm có thể khiến sếp hài lòng."},{"en":"Your application does not satisfy the requirements for this program.","vi":"Hồ sơ của bạn không đáp ứng các yêu cầu của chương trình này."}]', '[{"phrase":"satisfy customers"},{"phrase":"satisfy the requirements"},{"phrase":"satisfy demand"},{"phrase":"satisfy your curiosity"}]', NULL, '/ˈsætɪsfaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sat/satis/satisfy__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 5, 'chief', 'chính; chủ yếu; trưởng', 'adjective', '[{"en":"Cost was our chief concern when we chose a new apartment.","vi":"Chi phí là mối lo chính của chúng tôi khi chọn căn hộ mới."},{"en":"Her chief reason for moving was to be near her parents.","vi":"Lý do chủ yếu khiến cô ấy chuyển nhà là để ở gần bố mẹ."},{"en":"He works as the chief engineer at a large factory.","vi":"Anh ấy làm kỹ sư trưởng tại một nhà máy lớn."}]', '[{"phrase":"chief concern"},{"phrase":"chief reason"},{"phrase":"chief executive"}]', NULL, '/tʃiːf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/chi/chief/chief__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 6, 'cool', 'mát; bình tĩnh; ngầu', 'adjective', '[{"en":"It''s a bit cool this evening, so bring a jacket.","vi":"Tối nay trời hơi mát, nên hãy mang theo áo khoác."},{"en":"Try to stay cool, even when customers get angry.","vi":"Hãy cố giữ bình tĩnh, ngay cả khi khách hàng nổi giận."},{"en":"That''s a really cool bike you got for your birthday.","vi":"Chiếc xe đạp bạn được tặng dịp sinh nhật ngầu thật đấy."}]', '[{"phrase":"cool weather"},{"phrase":"stay cool"},{"phrase":"cool breeze"},{"phrase":"cool water"}]', NULL, '/kuːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coo/cool_/cool__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 7, 'expert', 'chuyên gia', 'noun', '[{"en":"You should ask an expert before you buy an old house.","vi":"Bạn nên hỏi ý kiến chuyên gia trước khi mua một ngôi nhà cũ."},{"en":"She is an expert on children''s health.","vi":"Cô ấy là chuyên gia về sức khỏe trẻ em."},{"en":"Experts say we should sleep at least seven hours a night.","vi":"Các chuyên gia cho rằng chúng ta nên ngủ ít nhất bảy tiếng mỗi đêm."}]', '[{"phrase":"expert on"},{"phrase":"expert in"},{"phrase":"health expert"},{"phrase":"expert advice"}]', NULL, '/ˈekspɜːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/exper/expert__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 8, 'wave', 'sóng; làn sóng; cái vẫy tay', 'noun', '[{"en":"The children laughed as the waves hit their feet.","vi":"Bọn trẻ cười vang khi những con sóng vỗ vào chân."},{"en":"A new wave of tourists arrives in the city every summer.","vi":"Mỗi mùa hè, một làn sóng du khách mới lại đổ về thành phố."},{"en":"She gave me a friendly wave from across the street.","vi":"Cô ấy thân thiện vẫy tay chào tôi từ bên kia đường."}]', '[{"phrase":"big waves"},{"phrase":"a wave of"},{"phrase":"give a wave"},{"phrase":"heat wave"}]', NULL, '/weɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wav/wave_/wave__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 9, 'south', 'phía nam; miền nam; hướng nam', 'noun', '[{"en":"My grandparents live in a small village in the south.","vi":"Ông bà tôi sống ở một ngôi làng nhỏ ở miền nam."},{"en":"The wind is blowing from the south today.","vi":"Hôm nay gió thổi từ hướng nam."},{"en":"The hotel is about twenty kilometers to the south of town.","vi":"Khách sạn nằm cách thị trấn khoảng hai mươi cây số về phía nam."}]', '[{"phrase":"in the south"},{"phrase":"to the south"},{"phrase":"from the south"},{"phrase":"south coast"}]', NULL, '/saʊθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sou/south/south__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 10, 'labor', 'lao động; nhân công', 'noun', '[{"en":"Labor costs have risen sharply in the last few years.","vi":"Chi phí nhân công đã tăng mạnh trong vài năm gần đây."},{"en":"The farm depends on cheap labor during the harvest season.","vi":"Trang trại phụ thuộc vào nhân công giá rẻ trong mùa thu hoạch."},{"en":"Farming still involves a lot of manual labor, even today.","vi":"Ngay cả ngày nay, làm nông vẫn đòi hỏi rất nhiều lao động chân tay."}]', '[{"phrase":"labor costs"},{"phrase":"cheap labor"},{"phrase":"manual labor"},{"phrase":"labor market"}]', 'Mỹ: labor · Anh: labour', '/ˈleɪbər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 11, 'surface', 'bề mặt; mặt nước; bề ngoài', 'noun', '[{"en":"Clean the kitchen surfaces with warm, soapy water.","vi":"Lau các bề mặt trong bếp bằng nước ấm pha xà phòng."},{"en":"Leaves were floating on the surface of the lake.","vi":"Lá cây trôi nổi trên mặt hồ."},{"en":"On the surface, he seemed calm, but he was very nervous.","vi":"Bề ngoài anh ấy có vẻ bình tĩnh, nhưng thật ra rất lo lắng."}]', '[{"phrase":"smooth surface"},{"phrase":"flat surface"},{"phrase":"on the surface"},{"phrase":"surface of the water"}]', NULL, '/ˈsɜːrfɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surfa/surface__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 12, 'library', 'thư viện', 'noun', '[{"en":"I borrowed three books from the library last week.","vi":"Tuần trước tôi đã mượn ba cuốn sách ở thư viện."},{"en":"The students often study in the library after class.","vi":"Sinh viên thường học ở thư viện sau giờ học."},{"en":"Our town is building a new public library near the park.","vi":"Thị trấn chúng tôi đang xây một thư viện công cộng mới gần công viên."}]', '[{"phrase":"public library"},{"phrase":"school library"},{"phrase":"library book"},{"phrase":"library card"}]', 'library (thư viện) ≠ bookstore (hiệu sách)', '/ˈlaɪbreri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lib/libra/library__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 13, 'excellent', 'xuất sắc; tuyệt vời', 'adjective', '[{"en":"The food at that little restaurant is excellent.","vi":"Đồ ăn ở nhà hàng nhỏ đó thật tuyệt vời."},{"en":"She speaks excellent English after living abroad for years.","vi":"Sau nhiều năm sống ở nước ngoài, cô ấy nói tiếng Anh xuất sắc."},{"en":"You did an excellent job on the presentation today.","vi":"Hôm nay bạn đã làm bài thuyết trình rất xuất sắc."}]', '[{"phrase":"excellent job"},{"phrase":"excellent condition"},{"phrase":"excellent opportunity"},{"phrase":"excellent food"}]', NULL, '/ˈeksələnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excel/excellent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 14, 'edge', 'mép; rìa; cạnh', 'noun', '[{"en":"Don''t put your glass so close to the edge of the table.","vi":"Đừng để cốc sát mép bàn như thế."},{"en":"They live in a quiet house on the edge of town.","vi":"Họ sống trong một ngôi nhà yên tĩnh ở rìa thị trấn."},{"en":"He cut his finger on the sharp edge of the paper.","vi":"Anh ấy bị đứt tay vì cạnh sắc của tờ giấy."}]', '[{"phrase":"on the edge of"},{"phrase":"edge of the table"},{"phrase":"sharp edge"},{"phrase":"the water''s edge"}]', NULL, '/edʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edg/edge_/edge__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 15, 'camp', 'trại; khu cắm trại', 'noun', '[{"en":"The kids are going to summer camp for two weeks.","vi":"Bọn trẻ sẽ đi trại hè trong hai tuần."},{"en":"We set up camp near the river before it got dark.","vi":"Chúng tôi dựng trại gần con sông trước khi trời tối."},{"en":"After a long hike, we finally returned to camp.","vi":"Sau một chuyến đi bộ đường dài, cuối cùng chúng tôi cũng về đến trại."}]', '[{"phrase":"summer camp"},{"phrase":"set up camp"},{"phrase":"training camp"}]', NULL, '/kæmp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cam/camp_/camp_1_us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 16, 'audience', 'khán giả; người xem; người nghe', 'noun', '[{"en":"The audience clapped loudly at the end of the show.","vi":"Khán giả vỗ tay rất lớn khi buổi diễn kết thúc."},{"en":"She felt nervous speaking in front of such a large audience.","vi":"Cô ấy thấy hồi hộp khi phát biểu trước đông khán giả như vậy."},{"en":"This TV program is aimed at a young audience.","vi":"Chương trình truyền hình này hướng đến người xem trẻ tuổi."}]', '[{"phrase":"large audience"},{"phrase":"live audience"},{"phrase":"target audience"},{"phrase":"young audience"}]', NULL, '/ˈɔːdiəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aud/audie/audience__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 17, 'lift', 'nâng; nhấc lên', 'verb', '[{"en":"Can you help me lift this heavy box onto the shelf?","vi":"Bạn giúp tôi nhấc cái hộp nặng này lên kệ được không?"},{"en":"She lifted the baby out of the car seat.","vi":"Cô ấy nhấc em bé ra khỏi ghế ngồi trên ô tô."},{"en":"My brother lifts weights at the gym three times a week.","vi":"Anh trai tôi tập tạ ở phòng gym ba lần một tuần."}]', '[{"phrase":"lift weights"},{"phrase":"lift your head"},{"phrase":"lift something heavy"}]', NULL, '/lɪft/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lif/lift_/lift__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 18, 'procedure', 'thủ tục; quy trình', 'noun', '[{"en":"Please follow the correct procedure when you report a problem.","vi":"Vui lòng làm đúng quy trình khi bạn báo cáo sự cố."},{"en":"The procedure for getting a visa can take several weeks.","vi":"Thủ tục xin thị thực có thể mất vài tuần."},{"en":"All staff must learn the safety procedures in case of fire.","vi":"Tất cả nhân viên phải nắm được các quy trình an toàn khi có hỏa hoạn."}]', '[{"phrase":"follow the procedure"},{"phrase":"safety procedures"},{"phrase":"standard procedure"},{"phrase":"emergency procedure"}]', NULL, '/prəˈsiːdʒər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proce/procedure__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 19, 'email', 'email; thư điện tử', 'noun', '[{"en":"I''ll send you an email with all the details tonight.","vi":"Tối nay tôi sẽ gửi cho bạn một email có đầy đủ chi tiết."},{"en":"She checks her email every morning before breakfast.","vi":"Sáng nào cô ấy cũng kiểm tra email trước khi ăn sáng."},{"en":"Did you get my email about the meeting on Friday?","vi":"Bạn đã nhận được email của tôi về cuộc họp hôm thứ Sáu chưa?"}]', '[{"phrase":"send an email"},{"phrase":"check your email"},{"phrase":"email address"},{"phrase":"reply to an email"}]', NULL, '/ˈiːmeɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ema/email/email__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 20, 'global', 'toàn cầu', 'adjective', '[{"en":"Climate change is a global problem that affects everyone.","vi":"Biến đổi khí hậu là vấn đề toàn cầu ảnh hưởng đến tất cả mọi người."},{"en":"The company now sells its products in the global market.","vi":"Công ty hiện bán sản phẩm của mình trên thị trường toàn cầu."},{"en":"Global demand for electric cars keeps growing every year.","vi":"Nhu cầu toàn cầu về ô tô điện tiếp tục tăng mỗi năm."}]', '[{"phrase":"global market"},{"phrase":"global economy"},{"phrase":"global warming"},{"phrase":"global problem"}]', NULL, '/ˈɡləʊbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/glo/globa/global__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 21, 'struggle', 'vật lộn; chật vật', 'verb', '[{"en":"Many families struggle to pay their rent each month.","vi":"Nhiều gia đình chật vật để trả tiền thuê nhà mỗi tháng."},{"en":"I struggled with math when I was at school.","vi":"Hồi còn đi học, tôi rất chật vật với môn toán."},{"en":"The old man struggled to open the heavy door.","vi":"Ông cụ vật lộn mãi mới mở được cánh cửa nặng."}]', '[{"phrase":"struggle to pay"},{"phrase":"struggle with"},{"phrase":"struggle to survive"}]', NULL, '/ˈstrʌɡl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strug/struggle__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 22, 'advertise', 'quảng cáo; đăng tin', 'verb', '[{"en":"The shop advertises its sales in the local newspaper.","vi":"Cửa hàng quảng cáo các đợt giảm giá trên báo địa phương."},{"en":"They are advertising for a new cook on their website.","vi":"Họ đang đăng tin tuyển đầu bếp mới trên trang web của mình."},{"en":"We advertised our old car online and sold it in two days.","vi":"Chúng tôi đăng tin bán chiếc xe cũ trên mạng và bán được sau hai ngày."}]', '[{"phrase":"advertise for"},{"phrase":"advertise online"},{"phrase":"advertise products"}]', NULL, '/ˈædvərtaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/adver/advertise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 23, 'select', 'chọn; lựa chọn', 'verb', '[{"en":"Select a language from the list and press Enter.","vi":"Chọn một ngôn ngữ trong danh sách rồi nhấn Enter."},{"en":"She was selected to play for the school team.","vi":"Cô ấy được chọn để chơi cho đội của trường."},{"en":"We carefully select the freshest fruit for our customers.","vi":"Chúng tôi cẩn thận lựa chọn trái cây tươi nhất cho khách hàng."}]', '[{"phrase":"select from"},{"phrase":"carefully select"},{"phrase":"be selected for"}]', NULL, '/sɪˈlekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sel/selec/select__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 24, 'surround', 'bao quanh; vây quanh', 'verb', '[{"en":"The old house is surrounded by tall trees.","vi":"Ngôi nhà cũ được bao quanh bởi những hàng cây cao."},{"en":"Fans surrounded the singer as she left the hotel.","vi":"Người hâm mộ vây quanh nữ ca sĩ khi cô rời khách sạn."},{"en":"It''s important to surround yourself with people who support you.","vi":"Điều quan trọng là để bản thân được bao quanh bởi những người ủng hộ bạn."}]', '[{"phrase":"surrounded by"},{"phrase":"surround yourself with"},{"phrase":"completely surrounded"}]', NULL, '/səˈraʊnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surro/surround__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 25, 'extent', 'mức độ; phạm vi', 'noun', '[{"en":"Doctors are still checking the extent of his injuries.","vi":"Các bác sĩ vẫn đang kiểm tra mức độ thương tích của anh ấy."},{"en":"I agree with you to some extent, but not completely.","vi":"Ở một mức độ nào đó tôi đồng ý với bạn, nhưng không hoàn toàn."},{"en":"We didn''t realize the full extent of the damage until morning.","vi":"Mãi đến sáng chúng tôi mới nhận ra hết mức độ thiệt hại."}]', '[{"phrase":"to some extent"},{"phrase":"to a large extent"},{"phrase":"the full extent"},{"phrase":"extent of the damage"}]', NULL, '/ɪkˈstent/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/exten/extent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 26, 'river', 'sông; dòng sông', 'noun', '[{"en":"We walked along the river after dinner.","vi":"Chúng tôi đi dạo dọc bờ sông sau bữa tối."},{"en":"The children love swimming in the river in summer.","vi":"Bọn trẻ thích bơi ở sông vào mùa hè."},{"en":"A new bridge is being built across the river.","vi":"Một cây cầu mới đang được xây bắc qua sông."}]', '[{"phrase":"along the river"},{"phrase":"across the river"},{"phrase":"cross the river"}]', NULL, '/ˈrɪvər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/riv/river/river__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 27, 'annual', 'hằng năm; thường niên', 'adjective', '[{"en":"The company holds its annual meeting every March.","vi":"Công ty tổ chức cuộc họp thường niên vào tháng Ba hằng năm."},{"en":"Our town''s annual flower festival attracts lots of visitors.","vi":"Lễ hội hoa hằng năm của thị trấn chúng tôi thu hút rất nhiều du khách."},{"en":"My annual salary went up by ten percent this year.","vi":"Năm nay lương hằng năm của tôi tăng mười phần trăm."}]', '[{"phrase":"annual meeting"},{"phrase":"annual salary"},{"phrase":"annual report"},{"phrase":"annual event"}]', NULL, '/ˈænjuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ann/annua/annual__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 28, 'fully', 'hoàn toàn; đầy đủ', 'adverb', '[{"en":"The hotel was fully booked for the holiday weekend.","vi":"Khách sạn đã kín hết phòng vào dịp nghỉ lễ cuối tuần."},{"en":"It takes about two hours to fully charge my phone.","vi":"Phải mất khoảng hai tiếng để sạc đầy điện thoại của tôi."},{"en":"I don''t fully understand what the teacher wants us to do.","vi":"Tôi chưa hoàn toàn hiểu thầy giáo muốn chúng tôi làm gì."}]', '[{"phrase":"fully understand"},{"phrase":"fully booked"},{"phrase":"fully aware"},{"phrase":"fully charged"}]', NULL, '/ˈfʊli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/ful/fully/fully__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 29, 'contrast', 'sự tương phản; sự trái ngược', 'noun', '[{"en":"There is a sharp contrast between life in the city and the countryside.","vi":"Có sự trái ngược rõ rệt giữa cuộc sống ở thành phố và ở nông thôn."},{"en":"The weather was cold, in contrast to the warm week before.","vi":"Thời tiết lạnh, trái ngược với tuần ấm áp trước đó."},{"en":"I like the contrast between the white walls and the dark floor.","vi":"Tôi thích sự tương phản giữa tường trắng và sàn nhà tối màu."}]', '[{"phrase":"in contrast"},{"phrase":"in contrast to"},{"phrase":"sharp contrast"},{"phrase":"contrast between"}]', NULL, '/ˈkɑːntræst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontrast__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-06', 30, 'roll', 'lăn; cuộn', 'verb', '[{"en":"The ball rolled under the car and I couldn''t reach it.","vi":"Quả bóng lăn xuống gầm xe và tôi không với tới được."},{"en":"Roll up the map carefully and put it back in the box.","vi":"Hãy cuộn tấm bản đồ lại cẩn thận rồi cất vào hộp."},{"en":"Tears rolled down her cheeks as she said goodbye.","vi":"Nước mắt lăn dài trên má cô ấy khi cô nói lời tạm biệt."}]', '[{"phrase":"roll down"},{"phrase":"roll up"},{"phrase":"roll over"}]', NULL, '/rəʊl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rol/roll_/roll__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-07', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 7', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 7);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 1, 'reality', 'thực tế; hiện thực', 'noun', '[{"en":"In reality, the job was much harder than I expected.","vi":"Trên thực tế, công việc khó hơn tôi nghĩ nhiều."},{"en":"Our dream of buying a house finally became a reality last year.","vi":"Giấc mơ mua nhà của chúng tôi cuối cùng đã thành hiện thực vào năm ngoái."},{"en":"Sometimes people watch movies to escape from reality for a while.","vi":"Đôi khi người ta xem phim để tạm thoát khỏi thực tế."}]', '[{"phrase":"in reality"},{"phrase":"become a reality"},{"phrase":"escape from reality"},{"phrase":"face reality"}]', NULL, '/riˈæləti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reali/reality__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 2, 'photograph', 'bức ảnh', 'noun', '[{"en":"She keeps an old photograph of her grandparents on her desk.","vi":"Cô ấy để một bức ảnh cũ của ông bà trên bàn làm việc."},{"en":"Could you take a photograph of us in front of the fountain?","vi":"Bạn có thể chụp giúp chúng tôi một bức ảnh trước đài phun nước không?"},{"en":"The photographs from our wedding are still in a box somewhere.","vi":"Những bức ảnh cưới của chúng tôi vẫn còn nằm trong một cái hộp ở đâu đó."}]', '[{"phrase":"take a photograph"},{"phrase":"old photograph"},{"phrase":"family photograph"}]', NULL, '/ˈfəʊtəɡræf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pho/photo/photograph__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 3, 'artist', 'nghệ sĩ; họa sĩ', 'noun', '[{"en":"My sister is a talented artist who paints mostly landscapes.","vi":"Chị tôi là một họa sĩ tài năng, chủ yếu vẽ tranh phong cảnh."},{"en":"The festival brings together local artists and musicians every summer.","vi":"Lễ hội quy tụ các nghệ sĩ và nhạc sĩ địa phương vào mỗi mùa hè."},{"en":"Which artist painted the picture hanging in your living room?","vi":"Họa sĩ nào đã vẽ bức tranh treo trong phòng khách nhà bạn?"}]', '[{"phrase":"talented artist"},{"phrase":"local artist"},{"phrase":"famous artist"}]', NULL, '/ˈɑːrtɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/art/artis/artist__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 4, 'conflict', 'xung đột; mâu thuẫn', 'noun', '[{"en":"There is often conflict between work and family life.","vi":"Công việc và cuộc sống gia đình thường có mâu thuẫn với nhau."},{"en":"The two neighbors tried to settle their conflict without going to court.","vi":"Hai người hàng xóm cố gắng giải quyết mâu thuẫn mà không phải ra tòa."},{"en":"A good manager knows how to handle conflict within a team.","vi":"Một người quản lý giỏi biết cách xử lý xung đột trong nhóm."}]', '[{"phrase":"resolve a conflict"},{"phrase":"conflict between"},{"phrase":"handle conflict"},{"phrase":"avoid conflict"}]', NULL, '/ˈkɑːnflɪkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconflict__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 5, 'entire', 'toàn bộ; cả', 'adjective', '[{"en":"I spent the entire weekend cleaning the house.","vi":"Tôi dành cả cuối tuần để dọn dẹp nhà cửa."},{"en":"The entire class passed the final exam this year.","vi":"Năm nay cả lớp đều đỗ kỳ thi cuối kỳ."},{"en":"She read the entire book in just one evening.","vi":"Cô ấy đọc hết cả cuốn sách chỉ trong một buổi tối."}]', '[{"phrase":"the entire day"},{"phrase":"the entire family"},{"phrase":"the entire class"}]', NULL, '/ɪnˈtaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/entir/entire__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 6, 'presence', 'sự có mặt; sự hiện diện', 'noun', '[{"en":"Your presence at the meeting is very important to us.","vi":"Sự có mặt của bạn tại cuộc họp rất quan trọng đối với chúng tôi."},{"en":"The children behaved well in the presence of their teacher.","vi":"Bọn trẻ cư xử ngoan ngoãn khi có mặt giáo viên."},{"en":"Police increased their presence in the city center during the festival.","vi":"Cảnh sát tăng cường sự hiện diện ở trung tâm thành phố trong dịp lễ hội."}]', '[{"phrase":"in the presence of"},{"phrase":"police presence"},{"phrase":"strong presence"}]', NULL, '/ˈprezns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prese/presence__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 7, 'crowd', 'đám đông', 'noun', '[{"en":"A large crowd gathered outside the stadium before the game.","vi":"Một đám đông lớn tụ tập bên ngoài sân vận động trước trận đấu."},{"en":"I lost sight of my son for a moment in the crowd.","vi":"Tôi mất dấu con trai một lúc giữa đám đông."},{"en":"We left early to avoid the crowds at the train station.","vi":"Chúng tôi đi sớm để tránh đám đông ở ga tàu."}]', '[{"phrase":"large crowd"},{"phrase":"huge crowd"},{"phrase":"avoid the crowds"},{"phrase":"in the crowd"}]', NULL, '/kraʊd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cro/crowd/crowd__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 8, 'corner', 'góc; góc phố', 'noun', '[{"en":"There is a small bakery on the corner of our street.","vi":"Có một tiệm bánh nhỏ ở góc phố nhà chúng tôi."},{"en":"Put the plant in the corner near the window.","vi":"Hãy đặt chậu cây vào góc gần cửa sổ."},{"en":"Turn left at the next corner, and you will see the bank.","vi":"Rẽ trái ở góc đường tiếp theo, bạn sẽ thấy ngân hàng."}]', '[{"phrase":"on the corner"},{"phrase":"in the corner"},{"phrase":"around the corner"},{"phrase":"street corner"}]', NULL, '/ˈkɔːrnər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/corne/corner__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 9, 'gas', 'khí; khí đốt; xăng', 'noun', '[{"en":"Plants take in a gas called carbon dioxide from the air.","vi":"Cây hấp thụ một loại khí gọi là carbon dioxide từ không khí."},{"en":"Please turn off the gas before you leave the kitchen.","vi":"Hãy tắt bếp ga trước khi rời khỏi bếp."},{"en":"We need to stop and get gas before the highway.","vi":"Chúng ta cần dừng lại đổ xăng trước khi lên đường cao tốc."}]', '[{"phrase":"natural gas"},{"phrase":"gas stove"},{"phrase":"run out of gas"},{"phrase":"turn off the gas"}]', 'Mỹ: gas · Anh: petrol (xăng)', '/ɡæs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gas/gas__/gas__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 10, 'shift', 'ca làm việc; sự thay đổi', 'noun', '[{"en":"My brother works the night shift at the hospital.","vi":"Anh tôi làm ca đêm ở bệnh viện."},{"en":"She starts her shift at six in the morning.","vi":"Cô ấy bắt đầu ca làm lúc sáu giờ sáng."},{"en":"There has been a shift in how people shop recently.","vi":"Gần đây đã có sự thay đổi trong cách mọi người mua sắm."}]', '[{"phrase":"night shift"},{"phrase":"day shift"},{"phrase":"work a shift"},{"phrase":"a shift in"}]', NULL, '/ʃɪft/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/shi/shift/shift__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 11, 'net', 'lưới; mạng internet', 'noun', '[{"en":"The fishermen pulled their nets out of the water at dawn.","vi":"Những người đánh cá kéo lưới lên khỏi mặt nước lúc bình minh."},{"en":"The ball hit the net and bounced back onto my side.","vi":"Quả bóng chạm lưới và bật ngược lại phía sân của tôi."},{"en":"My grandmother learned to surf the net at seventy.","vi":"Bà tôi học lướt mạng khi đã bảy mươi tuổi."}]', '[{"phrase":"fishing net"},{"phrase":"surf the net"},{"phrase":"safety net"}]', NULL, '/net/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/net/net__/net__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 12, 'category', 'loại; hạng mục', 'noun', '[{"en":"The books are sorted into categories such as history and science.","vi":"Sách được sắp xếp thành các loại như lịch sử và khoa học."},{"en":"Which category does this product belong to?","vi":"Sản phẩm này thuộc loại nào?"},{"en":"She won the prize in the best new writer category.","vi":"Cô ấy đã giành giải ở hạng mục nhà văn mới xuất sắc nhất."}]', '[{"phrase":"fall into a category"},{"phrase":"belong to a category"},{"phrase":"broad category"},{"phrase":"age category"}]', NULL, '/ˈkætəɡɔːri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cat/categ/category__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 13, 'secretary', 'thư ký', 'noun', '[{"en":"Please leave a message with my secretary if I am out.","vi":"Nếu tôi đi vắng, vui lòng để lại lời nhắn cho thư ký của tôi."},{"en":"The secretary booked a meeting room for Friday afternoon.","vi":"Cô thư ký đã đặt một phòng họp cho chiều thứ Sáu."},{"en":"My mother worked as a school secretary for twenty years.","vi":"Mẹ tôi làm thư ký trường học trong hai mươi năm."}]', '[{"phrase":"personal secretary"},{"phrase":"school secretary"},{"phrase":"work as a secretary"}]', NULL, '/ˈsekrəteri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secre/secretary__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 14, 'defense', 'sự bảo vệ; sự phòng thủ; hàng phòng ngự', 'noun', '[{"en":"Eating well is your body''s best defense against illness.","vi":"Ăn uống đầy đủ là cách tốt nhất để cơ thể bạn chống lại bệnh tật."},{"en":"He spoke in defense of his friend at the meeting.","vi":"Anh ấy lên tiếng bênh vực bạn mình tại cuộc họp."},{"en":"Our team needs a stronger defense to win this season.","vi":"Đội chúng tôi cần hàng phòng ngự mạnh hơn để giành chiến thắng mùa này."}]', '[{"phrase":"in defense of"},{"phrase":"defense against"},{"phrase":"strong defense"},{"phrase":"self-defense"}]', 'Mỹ: defense · Anh: defence', '/dɪˈfens/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defen/defence__us_12.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 15, 'quick', 'nhanh; ngắn, chóng vánh', 'adjective', '[{"en":"Can I ask you a quick question before you go?","vi":"Tôi hỏi bạn một câu ngắn trước khi bạn đi được không?"},{"en":"We had a quick lunch and went back to work.","vi":"Chúng tôi ăn trưa vội rồi quay lại làm việc."},{"en":"She is a quick learner and picks up new skills easily.","vi":"Cô ấy học rất nhanh và dễ dàng tiếp thu kỹ năng mới."}]', '[{"phrase":"quick question"},{"phrase":"quick lunch"},{"phrase":"quick learner"},{"phrase":"have a quick look"}]', NULL, '/kwɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qui/quick/quick__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 16, 'cook', 'nấu ăn; nấu', 'verb', '[{"en":"My father cooks dinner for the family every Sunday.","vi":"Bố tôi nấu bữa tối cho cả nhà vào mỗi Chủ nhật."},{"en":"Cook the rice for about fifteen minutes.","vi":"Nấu cơm trong khoảng mười lăm phút."},{"en":"I never learned how to cook when I lived with my parents.","vi":"Hồi sống với bố mẹ, tôi chưa bao giờ học nấu ăn."}]', '[{"phrase":"cook dinner"},{"phrase":"cook a meal"},{"phrase":"learn to cook"}]', NULL, '/kʊk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coo/cook_/cook__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 17, 'spread', 'lan rộng; phết; trải ra', 'verb', '[{"en":"The news spread quickly through the small town.","vi":"Tin tức lan nhanh khắp thị trấn nhỏ."},{"en":"She spread butter on her toast and poured some coffee.","vi":"Cô ấy phết bơ lên bánh mì nướng và rót một ít cà phê."},{"en":"We spread a blanket on the grass and had a picnic.","vi":"Chúng tôi trải một tấm chăn lên bãi cỏ rồi ngồi ăn dã ngoại."}]', '[{"phrase":"spread quickly"},{"phrase":"spread butter"},{"phrase":"spread the word"}]', 'spread – spread – spread', '/spred/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spr/sprea/spread__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 18, 'nuclear', 'hạt nhân', 'adjective', '[{"en":"The country gets much of its electricity from nuclear energy.","vi":"Đất nước này lấy phần lớn điện từ năng lượng hạt nhân."},{"en":"Many people worry about the safety of nuclear power plants.","vi":"Nhiều người lo ngại về độ an toàn của các nhà máy điện hạt nhân."},{"en":"In a nuclear family, children live with just their parents.","vi":"Trong gia đình hạt nhân, con cái chỉ sống cùng bố mẹ."}]', '[{"phrase":"nuclear energy"},{"phrase":"nuclear power"},{"phrase":"nuclear power plant"},{"phrase":"nuclear family"}]', NULL, '/ˈnuːkliər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nuc/nucle/nuclear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 19, 'scale', 'quy mô; thang đo; cái cân', 'noun', '[{"en":"The company wants to produce the new phone on a large scale.","vi":"Công ty muốn sản xuất chiếc điện thoại mới trên quy mô lớn."},{"en":"On a scale of one to ten, how was the movie?","vi":"Theo thang điểm từ một đến mười, bộ phim thế nào?"},{"en":"I stepped on the bathroom scale and got a surprise.","vi":"Tôi bước lên cân trong phòng tắm và giật mình."}]', '[{"phrase":"on a large scale"},{"phrase":"on a scale of"},{"phrase":"bathroom scale"},{"phrase":"the scale of the problem"}]', NULL, '/skeɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sca/scale/scale__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 20, 'driver', 'tài xế; người lái xe', 'noun', '[{"en":"The bus driver waited for the old man to sit down.","vi":"Tài xế xe buýt đợi ông cụ ngồi xuống."},{"en":"My sister is a careful driver and has never had an accident.","vi":"Chị tôi lái xe cẩn thận và chưa bao giờ gặp tai nạn."},{"en":"Ask the taxi driver to take you straight to the hotel.","vi":"Hãy bảo tài xế taxi đưa bạn thẳng đến khách sạn."}]', '[{"phrase":"bus driver"},{"phrase":"taxi driver"},{"phrase":"careful driver"},{"phrase":"driver''s license"}]', NULL, '/ˈdraɪvər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dri/drive/driver__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 21, 'ball', 'quả bóng', 'noun', '[{"en":"The kids are playing ball in the backyard.","vi":"Bọn trẻ đang chơi bóng ở sân sau."},{"en":"He kicked the ball over the fence by mistake.","vi":"Cậu ấy lỡ đá quả bóng bay qua hàng rào."},{"en":"Can you throw the ball to the dog, please?","vi":"Bạn ném quả bóng cho con chó được không?"}]', '[{"phrase":"kick a ball"},{"phrase":"throw a ball"},{"phrase":"catch a ball"},{"phrase":"play ball"}]', NULL, '/bɔːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bal/ball_/ball__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 22, 'cry', 'khóc; kêu to', 'verb', '[{"en":"The baby started to cry as soon as we left.","vi":"Em bé bắt đầu khóc ngay khi chúng tôi rời đi."},{"en":"She cried with joy when she heard the good news.","vi":"Cô ấy khóc vì vui sướng khi nghe tin tốt."},{"en":"Someone was crying for help from the river.","vi":"Có ai đó đang kêu cứu từ dưới sông."}]', '[{"phrase":"start to cry"},{"phrase":"cry for help"},{"phrase":"cry with joy"}]', NULL, '/kraɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cry/cry__/cry__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 23, 'introduction', 'sự giới thiệu; phần mở đầu', 'noun', '[{"en":"After a short introduction, the teacher started the lesson.","vi":"Sau phần giới thiệu ngắn, giáo viên bắt đầu bài học."},{"en":"Let me make the introductions before we start dinner.","vi":"Để tôi giới thiệu mọi người với nhau trước khi ăn tối nhé."},{"en":"Your essay needs a clearer introduction and conclusion.","vi":"Bài luận của bạn cần phần mở đầu và kết luận rõ ràng hơn."}]', '[{"phrase":"short introduction"},{"phrase":"brief introduction"},{"phrase":"make the introductions"},{"phrase":"introduction to"}]', NULL, '/ˌɪntrəˈdʌkʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/intro/introduction__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 24, 'requirement', 'yêu cầu; điều kiện', 'noun', '[{"en":"A good level of English is a requirement for this job.","vi":"Trình độ tiếng Anh tốt là một yêu cầu của công việc này."},{"en":"Please check the entry requirements before you apply to the university.","vi":"Vui lòng kiểm tra điều kiện đầu vào trước khi nộp đơn vào trường đại học."},{"en":"Does the new building meet all the safety requirements?","vi":"Tòa nhà mới có đáp ứng tất cả các yêu cầu an toàn không?"}]', '[{"phrase":"meet the requirements"},{"phrase":"entry requirements"},{"phrase":"safety requirements"},{"phrase":"minimum requirement"}]', NULL, '/rɪˈkwaɪərmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/req/requi/requirement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 25, 'north', 'phía bắc; miền bắc', 'noun', '[{"en":"My grandparents live in a small village in the north.","vi":"Ông bà tôi sống ở một ngôi làng nhỏ ở miền Bắc."},{"en":"The wind is coming from the north today.","vi":"Hôm nay gió thổi từ phía bắc."},{"en":"The lake is about twenty miles north of the city.","vi":"Hồ nằm cách thành phố khoảng hai mươi dặm về phía bắc."}]', '[{"phrase":"in the north"},{"phrase":"to the north"},{"phrase":"north of"},{"phrase":"the far north"}]', NULL, '/nɔːrθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nor/north/north__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 26, 'confirm', 'xác nhận; khẳng định', 'verb', '[{"en":"Please call the hotel to confirm our booking.","vi":"Làm ơn gọi cho khách sạn để xác nhận việc đặt phòng của chúng ta."},{"en":"The test results confirmed that he had a broken arm.","vi":"Kết quả kiểm tra khẳng định anh ấy bị gãy tay."},{"en":"Can you confirm the time of tomorrow''s meeting by email?","vi":"Bạn có thể xác nhận giờ họp ngày mai qua email không?"}]', '[{"phrase":"confirm a booking"},{"phrase":"confirm a reservation"},{"phrase":"officially confirm"}]', NULL, '/kənˈfɜːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfirm__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 27, 'senior', 'cấp cao; cao tuổi', 'adjective', '[{"en":"She was promoted to a senior position last month.","vi":"Tháng trước cô ấy được thăng lên một vị trí cấp cao."},{"en":"My uncle is a senior manager at a large bank.","vi":"Chú tôi là quản lý cấp cao tại một ngân hàng lớn."},{"en":"Senior citizens can travel on the bus for free.","vi":"Người cao tuổi được đi xe buýt miễn phí."}]', '[{"phrase":"senior manager"},{"phrase":"senior position"},{"phrase":"senior citizen"},{"phrase":"senior staff"}]', NULL, '/ˈsiːniər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sen/senio/senior__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 28, 'photo', 'ảnh', 'noun', '[{"en":"Let''s take a photo together before the sun goes down.","vi":"Mình chụp một tấm ảnh chung trước khi mặt trời lặn nhé."},{"en":"He posted a few photos from his trip online.","vi":"Anh ấy đăng vài tấm ảnh từ chuyến đi lên mạng."},{"en":"This photo of my dad was taken in 1990.","vi":"Tấm ảnh này của bố tôi được chụp vào năm 1990."}]', '[{"phrase":"take a photo"},{"phrase":"post a photo"},{"phrase":"family photo"},{"phrase":"photo album"}]', NULL, '/ˈfəʊtəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pho/photo/photo__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 29, 'refuse', 'từ chối; không chịu', 'verb', '[{"en":"He refused to answer any questions about his private life.","vi":"Anh ấy từ chối trả lời mọi câu hỏi về đời tư."},{"en":"My little brother refuses to eat vegetables.","vi":"Em trai tôi không chịu ăn rau."},{"en":"They offered her the job, but she refused.","vi":"Họ mời cô ấy nhận công việc đó, nhưng cô ấy đã từ chối."}]', '[{"phrase":"refuse to do something"},{"phrase":"refuse an offer"},{"phrase":"flatly refuse"}]', NULL, '/rɪˈfjuːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refus/refuse__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-07', 30, 'transport', 'giao thông vận tải; phương tiện đi lại', 'noun', '[{"en":"The city has good public transport, so I rarely drive.","vi":"Thành phố có giao thông công cộng tốt nên tôi hiếm khi lái xe."},{"en":"Bikes are a cheap and healthy form of transport.","vi":"Xe đạp là một phương tiện đi lại rẻ và tốt cho sức khỏe."},{"en":"The price includes hotel, meals and transport to the airport.","vi":"Giá đã bao gồm khách sạn, bữa ăn và xe đưa đón ra sân bay."}]', '[{"phrase":"public transport"},{"phrase":"form of transport"},{"phrase":"means of transport"},{"phrase":"transport costs"}]', 'Anh: public transport · Mỹ: public transportation', '/ˈtrænspɔːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transport__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-08', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 8', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 8);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 1, 'emerge', 'xuất hiện; hiện ra; lộ ra', 'verb', '[{"en":"The sun finally emerged from behind the clouds in the afternoon.","vi":"Buổi chiều, mặt trời cuối cùng cũng ló ra từ sau những đám mây."},{"en":"A cat suddenly emerged from under the car and ran away.","vi":"Một con mèo bất ngờ chui ra từ gầm xe rồi chạy mất."},{"en":"New details about the accident emerged a few days later.","vi":"Vài ngày sau, những chi tiết mới về vụ tai nạn đã lộ ra."}]', '[{"phrase":"emerge from"},{"phrase":"begin to emerge"},{"phrase":"new evidence emerged"}]', 'emerge from + nơi chốn', '/ɪˈmɜːrdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eme/emerg/emerge__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 2, 'map', 'bản đồ', 'noun', '[{"en":"Can you show me where we are on the map?","vi":"Bạn có thể chỉ cho tôi chúng ta đang ở đâu trên bản đồ không?"},{"en":"I always check the map on my phone before I drive somewhere new.","vi":"Tôi luôn xem bản đồ trên điện thoại trước khi lái xe đến nơi mới."},{"en":"There is a large map of the world on the classroom wall.","vi":"Trên tường lớp học có một tấm bản đồ thế giới lớn."}]', '[{"phrase":"on the map"},{"phrase":"read a map"},{"phrase":"a map of the world"},{"phrase":"street map"}]', NULL, '/mæp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/map/map__/map__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 3, 'concept', 'khái niệm; ý tưởng', 'noun', '[{"en":"Young children often find the concept of time hard to understand.","vi":"Trẻ nhỏ thường thấy khái niệm thời gian khó hiểu."},{"en":"The teacher used simple examples to explain a difficult concept.","vi":"Giáo viên dùng những ví dụ đơn giản để giải thích một khái niệm khó."},{"en":"Our team liked the concept, but the design still needs work.","vi":"Nhóm chúng tôi thích ý tưởng này, nhưng thiết kế vẫn cần chỉnh sửa thêm."}]', '[{"phrase":"basic concept"},{"phrase":"the concept of"},{"phrase":"understand the concept"},{"phrase":"new concept"}]', NULL, '/ˈkɑːnsept/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcept__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 4, 'island', 'hòn đảo; đảo', 'noun', '[{"en":"We took a boat to a small island near the coast.","vi":"Chúng tôi đi thuyền ra một hòn đảo nhỏ gần bờ biển."},{"en":"Only a few hundred people live on the island all year.","vi":"Chỉ có vài trăm người sống trên đảo quanh năm."},{"en":"Have you ever spent a holiday on a tropical island?","vi":"Bạn đã bao giờ đi nghỉ ở một hòn đảo nhiệt đới chưa?"}]', '[{"phrase":"on the island"},{"phrase":"small island"},{"phrase":"tropical island"},{"phrase":"desert island"}]', 'Chữ s trong island không đọc', '/ˈaɪlənd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/isl/islan/island__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 5, 'reform', 'cải cách; sự cải tổ', 'noun', '[{"en":"Many teachers believe the school system needs serious reform.","vi":"Nhiều giáo viên cho rằng hệ thống trường học cần được cải cách nghiêm túc."},{"en":"The tax reform will make life easier for small businesses.","vi":"Cuộc cải cách thuế sẽ giúp các doanh nghiệp nhỏ dễ thở hơn."},{"en":"The city introduced several reforms to improve public transport.","vi":"Thành phố đã đưa ra một số cải cách để cải thiện giao thông công cộng."}]', '[{"phrase":"economic reform"},{"phrase":"tax reform"},{"phrase":"education reform"},{"phrase":"introduce reforms"}]', NULL, '/rɪˈfɔːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refor/reform__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 6, 'neither', 'không cái nào (trong hai); cũng không', 'determiner', '[{"en":"Neither answer is correct, so please try again.","vi":"Cả hai câu trả lời đều không đúng, vậy hãy thử lại nhé."},{"en":"I tried two shirts, but neither of them fit me well.","vi":"Tôi đã thử hai chiếc áo, nhưng chẳng chiếc nào vừa với tôi."},{"en":"She doesn''t eat meat, and neither does her husband.","vi":"Cô ấy không ăn thịt, và chồng cô ấy cũng không."}]', '[{"phrase":"neither of them"},{"phrase":"neither ... nor"},{"phrase":"neither do I"}]', 'neither A nor B = không A cũng không B', '/ˈniːðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nei/neith/neither__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 7, 'football', 'bóng đá; quả bóng đá', 'noun', '[{"en":"My brother plays football with his friends every Saturday morning.","vi":"Anh trai tôi đá bóng với bạn bè vào mỗi sáng thứ Bảy."},{"en":"We watched the football match on TV last night.","vi":"Tối qua chúng tôi xem trận bóng đá trên TV."},{"en":"The kids kicked the football over the fence into the garden.","vi":"Bọn trẻ đá quả bóng qua hàng rào rơi vào khu vườn."}]', '[{"phrase":"play football"},{"phrase":"football match"},{"phrase":"football team"},{"phrase":"football fan"}]', 'Ở Mỹ, football thường chỉ bóng bầu dục; bóng đá là soccer', '/ˈfʊtbɔːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/foo/footb/football__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 8, 'survive', 'sống sót; tồn tại; vượt qua', 'verb', '[{"en":"Everyone on the boat survived the storm without serious injuries.","vi":"Mọi người trên thuyền đều sống sót qua cơn bão mà không bị thương nặng."},{"en":"Plants cannot survive for long without water and light.","vi":"Cây cối không thể sống lâu nếu thiếu nước và ánh sáng."},{"en":"The small shop survived for fifty years in the same street.","vi":"Cửa hàng nhỏ đã tồn tại năm mươi năm trên cùng một con phố."}]', '[{"phrase":"survive the accident"},{"phrase":"manage to survive"},{"phrase":"struggle to survive"},{"phrase":"survive on"}]', NULL, '/sərˈvaɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/survi/survive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 9, 'flight', 'chuyến bay; sự bay', 'noun', '[{"en":"Our flight to Singapore was delayed for two hours.","vi":"Chuyến bay của chúng tôi đến Singapore bị hoãn hai tiếng."},{"en":"I usually try to sleep during long flights.","vi":"Tôi thường cố gắng ngủ trong những chuyến bay dài."},{"en":"She booked a cheap flight home for the holidays.","vi":"Cô ấy đã đặt một chuyến bay giá rẻ về nhà dịp nghỉ lễ."}]', '[{"phrase":"book a flight"},{"phrase":"catch a flight"},{"phrase":"long flight"},{"phrase":"flight attendant"}]', NULL, '/flaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fli/fligh/flight__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 10, 'left', 'bên trái; (phía) trái', 'adjective', '[{"en":"He broke his left arm when he fell off his bike.","vi":"Anh ấy bị gãy tay trái khi ngã xe đạp."},{"en":"Turn left at the next corner, and the bank is on your right.","vi":"Rẽ trái ở góc đường tiếp theo, ngân hàng nằm bên tay phải bạn."},{"en":"The bathroom is the second door on the left.","vi":"Nhà vệ sinh là cánh cửa thứ hai bên trái."}]', '[{"phrase":"turn left"},{"phrase":"on the left"},{"phrase":"left hand"},{"phrase":"left side"}]', 'left cũng là quá khứ của leave (rời đi)', '/left/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lef/left_/left__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 11, 'solve', 'giải quyết; giải (bài toán)', 'verb', '[{"en":"We need to solve this problem before the customer calls again.","vi":"Chúng ta cần giải quyết vấn đề này trước khi khách hàng gọi lại."},{"en":"Talking openly can help solve many family arguments.","vi":"Nói chuyện cởi mở có thể giúp giải quyết nhiều cuộc cãi vã trong gia đình."},{"en":"My son solved all the math problems in ten minutes.","vi":"Con trai tôi đã giải hết các bài toán trong mười phút."}]', '[{"phrase":"solve a problem"},{"phrase":"solve a puzzle"},{"phrase":"solve the mystery"},{"phrase":"help solve"}]', NULL, '/sɑːlv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sol/solve/solve__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 12, 'neighbor', 'hàng xóm; người láng giềng', 'noun', '[{"en":"Our new neighbors invited us over for dinner on Sunday.","vi":"Hàng xóm mới mời chúng tôi sang ăn tối vào Chủ nhật."},{"en":"My neighbor waters my plants when I''m away on vacation.","vi":"Người hàng xóm tưới cây giúp tôi khi tôi đi nghỉ."},{"en":"The kids next door are always noisy, but they are good neighbors.","vi":"Lũ trẻ nhà bên lúc nào cũng ồn ào, nhưng họ là những người hàng xóm tốt."}]', '[{"phrase":"next-door neighbor"},{"phrase":"good neighbor"},{"phrase":"new neighbors"},{"phrase":"close neighbor"}]', 'Anh: neighbour · Mỹ: neighbor', '/ˈneɪbər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 13, 'background', 'lý lịch; xuất thân; nền (phía sau)', 'noun', '[{"en":"Students in my class come from many different backgrounds.","vi":"Sinh viên trong lớp tôi đến từ nhiều hoàn cảnh xuất thân khác nhau."},{"en":"She has a strong background in science and engineering.","vi":"Cô ấy có nền tảng vững chắc về khoa học và kỹ thuật."},{"en":"In the photo, you can see the mountains in the background.","vi":"Trong bức ảnh, bạn có thể thấy những ngọn núi ở phía sau."}]', '[{"phrase":"in the background"},{"phrase":"family background"},{"phrase":"different backgrounds"},{"phrase":"background music"}]', NULL, '/ˈbækɡraʊnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bac/backg/background__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 14, 'technique', 'kỹ thuật; phương pháp', 'noun', '[{"en":"The coach showed us a simple technique for breathing while swimming.","vi":"Huấn luyện viên chỉ cho chúng tôi một kỹ thuật thở đơn giản khi bơi."},{"en":"This cooking technique keeps the vegetables fresh and green.","vi":"Kỹ thuật nấu ăn này giữ cho rau tươi và xanh."},{"en":"Have you tried any new techniques for learning vocabulary?","vi":"Bạn đã thử phương pháp mới nào để học từ vựng chưa?"}]', '[{"phrase":"use a technique"},{"phrase":"learn a technique"},{"phrase":"new technique"},{"phrase":"basic technique"}]', NULL, '/tekˈniːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tec/techn/technique__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 15, 'traffic', 'giao thông; xe cộ lưu thông', 'noun', '[{"en":"I was late for work because the traffic was terrible.","vi":"Tôi đi làm muộn vì giao thông quá tệ."},{"en":"There is always heavy traffic on this road in the morning.","vi":"Buổi sáng con đường này lúc nào cũng đông xe."},{"en":"We got stuck in traffic for an hour on the way home.","vi":"Trên đường về nhà, chúng tôi bị kẹt xe một tiếng."}]', '[{"phrase":"heavy traffic"},{"phrase":"stuck in traffic"},{"phrase":"traffic jam"},{"phrase":"traffic lights"}]', 'không đếm được', '/ˈtræfɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/traff/traffic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 16, 'improvement', 'sự cải thiện; sự tiến bộ', 'noun', '[{"en":"There has been a big improvement in your English this year.","vi":"Năm nay tiếng Anh của bạn đã tiến bộ rất nhiều."},{"en":"The new manager made several improvements to the office.","vi":"Người quản lý mới đã thực hiện một số cải thiện cho văn phòng."},{"en":"Doctors say there has been a slight improvement in his condition.","vi":"Các bác sĩ cho biết tình trạng của anh ấy đã cải thiện đôi chút."}]', '[{"phrase":"big improvement"},{"phrase":"improvement in"},{"phrase":"room for improvement"},{"phrase":"make improvements"}]', NULL, '/ɪmˈpruːvmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impro/improvement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 17, 'tool', 'dụng cụ; công cụ', 'noun', '[{"en":"My father keeps all his tools in a box in the garage.","vi":"Bố tôi cất tất cả dụng cụ trong một chiếc hộp ở nhà để xe."},{"en":"You need the right tools to fix a bike properly.","vi":"Bạn cần đúng dụng cụ để sửa xe đạp cho tốt."},{"en":"The internet can be a useful tool for learning languages.","vi":"Internet có thể là một công cụ hữu ích để học ngoại ngữ."}]', '[{"phrase":"useful tool"},{"phrase":"garden tools"},{"phrase":"power tools"},{"phrase":"a tool for"}]', NULL, '/tuːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/too/tool_/tool__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 18, 'consequence', 'hậu quả; kết quả', 'noun', '[{"en":"If you break the rules, you must accept the consequences.","vi":"Nếu bạn vi phạm nội quy, bạn phải chấp nhận hậu quả."},{"en":"Missing too many classes can have serious consequences for your grades.","vi":"Nghỉ học quá nhiều có thể gây hậu quả nghiêm trọng cho điểm số của bạn."},{"en":"He didn''t think about the consequences before he quit his job.","vi":"Anh ấy đã không nghĩ đến hậu quả trước khi nghỉ việc."}]', '[{"phrase":"serious consequences"},{"phrase":"accept the consequences"},{"phrase":"as a consequence"},{"phrase":"consequences of"}]', NULL, '/ˈkɑːnsɪkwens/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsequence__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 19, 'circumstance', 'hoàn cảnh; tình huống', 'noun', '[{"en":"Under normal circumstances, the train takes about three hours.","vi":"Trong điều kiện bình thường, tàu chạy mất khoảng ba tiếng."},{"en":"You should not open this door under any circumstances.","vi":"Bạn không được mở cánh cửa này trong bất kỳ trường hợp nào."},{"en":"Given the circumstances, I think you made the right decision.","vi":"Xét theo hoàn cảnh, tôi nghĩ bạn đã quyết định đúng."}]', '[{"phrase":"under the circumstances"},{"phrase":"under no circumstances"},{"phrase":"in certain circumstances"},{"phrase":"personal circumstances"}]', 'Thường dùng số nhiều: circumstances', '/ˈsɜːrkəmstæns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cir/circu/circumstance__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 20, 'smoke', 'khói', 'noun', '[{"en":"We saw black smoke coming from the kitchen window.","vi":"Chúng tôi thấy khói đen bốc ra từ cửa sổ nhà bếp."},{"en":"The smoke from the fire made everyone''s eyes water.","vi":"Khói từ đám cháy làm mắt mọi người chảy nước."},{"en":"I opened all the windows to let the smoke out.","vi":"Tôi mở hết cửa sổ cho khói bay ra ngoài."}]', '[{"phrase":"black smoke"},{"phrase":"cigarette smoke"},{"phrase":"smoke alarm"},{"phrase":"a cloud of smoke"}]', 'không đếm được; smoke (v) = hút thuốc', '/sməʊk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/smo/smoke/smoke__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 21, 'reaction', 'phản ứng', 'noun', '[{"en":"What was your parents'' reaction when you told them the news?","vi":"Bố mẹ bạn phản ứng thế nào khi bạn báo tin cho họ?"},{"en":"Some people have an allergic reaction to nuts.","vi":"Một số người bị phản ứng dị ứng với các loại hạt."},{"en":"The new product got a very positive reaction from customers.","vi":"Sản phẩm mới nhận được phản ứng rất tích cực từ khách hàng."}]', '[{"phrase":"reaction to"},{"phrase":"allergic reaction"},{"phrase":"positive reaction"},{"phrase":"first reaction"}]', NULL, '/riˈækʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/react/reaction__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 22, 'rain', 'mưa; cơn mưa', 'noun', '[{"en":"Don''t forget your umbrella, because heavy rain is expected today.","vi":"Đừng quên mang ô nhé, vì hôm nay dự báo có mưa to."},{"en":"We waited in a café until the rain stopped.","vi":"Chúng tôi ngồi đợi trong quán cà phê cho đến khi tạnh mưa."},{"en":"The kids love walking in the rain in their boots.","vi":"Bọn trẻ rất thích mang ủng đi dạo dưới mưa."}]', '[{"phrase":"heavy rain"},{"phrase":"in the rain"},{"phrase":"the rain stops"},{"phrase":"light rain"}]', NULL, '/reɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rai/rain_/rain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 23, 'busy', 'bận; đông đúc; (máy) bận', 'adjective', '[{"en":"I''m too busy to go out for lunch today.","vi":"Hôm nay tôi bận quá không đi ăn trưa được."},{"en":"The market is always busy on weekend mornings.","vi":"Chợ lúc nào cũng đông đúc vào các buổi sáng cuối tuần."},{"en":"I called the office twice, but the line was busy.","vi":"Tôi đã gọi đến văn phòng hai lần nhưng máy đều bận."}]', '[{"phrase":"busy day"},{"phrase":"busy street"},{"phrase":"keep busy"},{"phrase":"busy with"}]', 'busy + V-ing: bận làm gì', '/ˈbɪzi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bus/busy_/busy__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 24, 'lesson', 'bài học; buổi học', 'noun', '[{"en":"My daughter has piano lessons twice a week after school.","vi":"Con gái tôi học piano hai buổi mỗi tuần sau giờ học."},{"en":"Today''s lesson is about how to write a formal email.","vi":"Bài học hôm nay là về cách viết một email trang trọng."},{"en":"Losing my wallet taught me an important lesson.","vi":"Việc làm mất ví đã dạy cho tôi một bài học quan trọng."}]', '[{"phrase":"take lessons"},{"phrase":"learn a lesson"},{"phrase":"driving lessons"},{"phrase":"teach someone a lesson"}]', NULL, '/ˈlesn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/les/lesso/lesson__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 25, 'brain', 'não; bộ óc; trí tuệ', 'noun', '[{"en":"Getting enough sleep is important for a healthy brain.","vi":"Ngủ đủ giấc rất quan trọng để có một bộ não khỏe mạnh."},{"en":"Reading every day keeps your brain active as you get older.","vi":"Đọc sách mỗi ngày giúp não bạn luôn hoạt động khi về già."},{"en":"She has the brains to become a great doctor.","vi":"Cô ấy đủ thông minh để trở thành một bác sĩ giỏi."}]', '[{"phrase":"human brain"},{"phrase":"brain damage"},{"phrase":"use your brain"},{"phrase":"brain activity"}]', NULL, '/breɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bra/brain/brain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 26, 'mass', 'khối; số đông; đại chúng', 'noun', '[{"en":"A mass of dark clouds was moving toward the city.","vi":"Một khối mây đen đang tiến về phía thành phố."},{"en":"The singer''s songs were popular with the masses.","vi":"Những bài hát của ca sĩ đó được đông đảo quần chúng yêu thích."},{"en":"Mass tourism has changed life in many small beach towns.","vi":"Du lịch đại chúng đã làm thay đổi cuộc sống ở nhiều thị trấn biển nhỏ."}]', '[{"phrase":"a mass of"},{"phrase":"the masses"},{"phrase":"mass production"},{"phrase":"mass media"}]', NULL, '/mæs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mas/mass_/mass__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 27, 'funny', 'buồn cười; hài hước; kỳ lạ', 'adjective', '[{"en":"My grandfather always tells funny stories at family dinners.","vi":"Ông tôi luôn kể những câu chuyện hài hước trong các bữa tối gia đình."},{"en":"We watched a really funny movie and laughed all night.","vi":"Chúng tôi xem một bộ phim rất buồn cười và cười suốt cả tối."},{"en":"The engine is making a funny noise, so I should check it.","vi":"Động cơ đang phát ra tiếng kêu lạ, nên tôi phải kiểm tra."}]', '[{"phrase":"funny story"},{"phrase":"funny thing"},{"phrase":"funny feeling"},{"phrase":"look funny"}]', NULL, '/ˈfʌni/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/funny/funny__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 28, 'contribute', 'đóng góp; góp phần', 'verb', '[{"en":"Everyone contributed some money to buy a gift for the teacher.","vi":"Mọi người góp một ít tiền để mua quà tặng cô giáo."},{"en":"Lack of sleep can contribute to health problems.","vi":"Thiếu ngủ có thể góp phần gây ra các vấn đề sức khỏe."},{"en":"I hope I can contribute useful ideas at the meeting.","vi":"Tôi hy vọng có thể đóng góp những ý tưởng hữu ích trong cuộc họp."}]', '[{"phrase":"contribute to"},{"phrase":"contribute money"},{"phrase":"contribute ideas"},{"phrase":"contribute significantly"}]', 'contribute to + danh từ/V-ing', '/kənˈtrɪbjuːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontribute__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 29, 'failure', 'sự thất bại; sự hỏng hóc', 'noun', '[{"en":"Don''t be afraid of failure, because everyone makes mistakes.","vi":"Đừng sợ thất bại, vì ai cũng mắc sai lầm."},{"en":"His first business was a failure, but he tried again.","vi":"Việc kinh doanh đầu tiên của anh ấy thất bại, nhưng anh ấy đã thử lại."},{"en":"The flight was canceled because of an engine failure.","vi":"Chuyến bay bị hủy do động cơ gặp sự cố."}]', '[{"phrase":"fear of failure"},{"phrase":"end in failure"},{"phrase":"complete failure"},{"phrase":"engine failure"}]', NULL, '/ˈfeɪljər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fai/failu/failure__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-08', 30, 'schedule', 'lịch trình; thời gian biểu', 'noun', '[{"en":"My work schedule is very busy this week.","vi":"Lịch làm việc của tôi tuần này rất dày đặc."},{"en":"The project is two weeks behind schedule.","vi":"Dự án đang chậm hai tuần so với tiến độ."},{"en":"Can you check the train schedule for Sunday morning?","vi":"Bạn xem giúp lịch tàu sáng Chủ nhật được không?"}]', '[{"phrase":"busy schedule"},{"phrase":"on schedule"},{"phrase":"behind schedule"},{"phrase":"train schedule"}]', NULL, '/ˈskedʒuːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sch/sched/schedule__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-09', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 9', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 9);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 1, 'speaker', 'người phát biểu, diễn giả; người nói (một ngôn ngữ); loa', 'noun', '[{"en":"The guest speaker talked about her years working in Africa.","vi":"Diễn giả khách mời đã nói về những năm cô ấy làm việc ở châu Phi."},{"en":"He is a native speaker of Spanish, so ask him for help.","vi":"Anh ấy là người bản ngữ nói tiếng Tây Ban Nha, nên hãy nhờ anh ấy giúp."},{"en":"Can you turn down the speakers? The music is too loud.","vi":"Bạn vặn nhỏ loa được không? Nhạc to quá."}]', '[{"phrase":"guest speaker"},{"phrase":"native speaker"},{"phrase":"public speaker"},{"phrase":"keynote speaker"}]', NULL, '/ˈspiːkər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speak/speaker__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 2, 'bottom', 'đáy; phần dưới cùng, cuối', 'noun', '[{"en":"I found my keys at the bottom of my bag.","vi":"Tôi tìm thấy chìa khóa ở dưới đáy túi."},{"en":"Please sign your name at the bottom of the page.","vi":"Vui lòng ký tên ở cuối trang."},{"en":"We waited at the bottom of the hill for the others.","vi":"Chúng tôi đợi những người khác ở chân đồi."}]', '[{"phrase":"at the bottom of"},{"phrase":"the bottom of the page"},{"phrase":"bottom line"}]', NULL, '/ˈbɑːtəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bot/botto/bottom__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 3, 'adopt', 'nhận nuôi; áp dụng', 'verb', '[{"en":"They decided to adopt a little girl from another country.","vi":"Họ quyết định nhận nuôi một bé gái từ nước khác."},{"en":"We adopted a cat from the animal shelter last month.","vi":"Tháng trước chúng tôi đã nhận nuôi một con mèo từ trại cứu hộ động vật."},{"en":"The school has adopted a new approach to teaching reading.","vi":"Trường đã áp dụng một cách tiếp cận mới trong việc dạy đọc."}]', '[{"phrase":"adopt a child"},{"phrase":"adopt an approach"},{"phrase":"adopt a policy"}]', 'adopt (nhận nuôi, áp dụng) ≠ adapt (thích nghi)', '/əˈdɑːpt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ado/adopt/adopt__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 4, 'combine', 'kết hợp; phối hợp', 'verb', '[{"en":"Combine the flour and sugar in a large bowl.","vi":"Trộn bột mì và đường trong một cái bát lớn."},{"en":"It''s hard to combine a full-time job with studying.","vi":"Thật khó để vừa làm việc toàn thời gian vừa đi học."},{"en":"Our team won because we combined our different skills.","vi":"Đội chúng tôi thắng vì đã kết hợp những kỹ năng khác nhau của mọi người."}]', '[{"phrase":"combine with"},{"phrase":"combine work with family"},{"phrase":"combined effort"}]', 'combine A with B', '/kəmˈbaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/combi/combine__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 5, 'mountain', 'núi', 'noun', '[{"en":"We climbed the mountain and enjoyed the view from the top.","vi":"Chúng tôi leo lên núi và ngắm cảnh từ trên đỉnh."},{"en":"My grandparents live in a small village in the mountains.","vi":"Ông bà tôi sống ở một ngôi làng nhỏ trên núi."},{"en":"Snow covers the mountains for most of the winter.","vi":"Tuyết phủ kín những ngọn núi gần như suốt mùa đông."}]', '[{"phrase":"climb a mountain"},{"phrase":"in the mountains"},{"phrase":"mountain top"},{"phrase":"mountain range"}]', NULL, '/ˈmaʊntn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mou/mount/mountain__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 6, 'waste', 'lãng phí; rác thải', 'noun', '[{"en":"That meeting was a complete waste of time.","vi":"Cuộc họp đó hoàn toàn là phí thời gian."},{"en":"Buying clothes you never wear is a waste of money.","vi":"Mua quần áo mà không bao giờ mặc là lãng phí tiền bạc."},{"en":"The city is trying to reduce the amount of food waste.","vi":"Thành phố đang cố gắng giảm lượng rác thải thực phẩm."}]', '[{"phrase":"a waste of time"},{"phrase":"a waste of money"},{"phrase":"food waste"},{"phrase":"reduce waste"}]', NULL, '/weɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/was/waste/waste__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 7, 'hide', 'trốn; giấu, che giấu', 'verb', '[{"en":"The children hid behind the door when their father came home.","vi":"Bọn trẻ trốn sau cánh cửa khi bố chúng về nhà."},{"en":"She hid the birthday present under her bed.","vi":"Cô ấy giấu món quà sinh nhật dưới gầm giường."},{"en":"He tried to hide his feelings, but everyone could see he was upset.","vi":"Anh ấy cố che giấu cảm xúc, nhưng ai cũng thấy anh ấy đang buồn."}]', '[{"phrase":"hide something from someone"},{"phrase":"hide behind"},{"phrase":"hide your feelings"},{"phrase":"hide the truth"}]', 'hide – hid – hidden', '/haɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hid/hide_/hide__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 8, 'marriage', 'hôn nhân; cuộc hôn nhân', 'noun', '[{"en":"My parents have had a long and happy marriage.","vi":"Bố mẹ tôi đã có một cuộc hôn nhân lâu dài và hạnh phúc."},{"en":"She has two children from her first marriage.","vi":"Cô ấy có hai con từ cuộc hôn nhân đầu tiên."},{"en":"Good communication is important in any marriage.","vi":"Giao tiếp tốt rất quan trọng trong bất kỳ cuộc hôn nhân nào."}]', '[{"phrase":"happy marriage"},{"phrase":"first marriage"},{"phrase":"marriage proposal"}]', 'marriage (n) – married (adj) – marry (v)', '/ˈmærɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mar/marri/marriage__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 9, 'ticket', 'vé; giấy phạt', 'noun', '[{"en":"I bought two tickets for the concert on Saturday.","vi":"Tôi đã mua hai vé xem buổi hòa nhạc vào thứ Bảy."},{"en":"How much is a round-trip ticket to the city center?","vi":"Vé khứ hồi vào trung tâm thành phố giá bao nhiêu?"},{"en":"He got a parking ticket because he stayed too long.","vi":"Anh ấy bị phạt đỗ xe vì đỗ quá lâu."}]', '[{"phrase":"buy a ticket"},{"phrase":"train ticket"},{"phrase":"one-way ticket"},{"phrase":"parking ticket"}]', NULL, '/ˈtɪkɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tic/ticke/ticket__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 10, 'meal', 'bữa ăn', 'noun', '[{"en":"We usually eat our main meal in the evening.","vi":"Chúng tôi thường ăn bữa chính vào buổi tối."},{"en":"Thank you for the lovely meal last night.","vi":"Cảm ơn bạn vì bữa ăn tuyệt vời tối qua."},{"en":"Try not to snack between meals if you want to lose weight.","vi":"Nếu muốn giảm cân, hãy cố đừng ăn vặt giữa các bữa ăn."}]', '[{"phrase":"main meal"},{"phrase":"have a meal"},{"phrase":"cook a meal"},{"phrase":"between meals"}]', NULL, '/miːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mea/meal_/meal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 11, 'colleague', 'đồng nghiệp', 'noun', '[{"en":"I often have lunch with my colleagues from the office.","vi":"Tôi thường ăn trưa với các đồng nghiệp ở văn phòng."},{"en":"A colleague helped me finish the report on time.","vi":"Một đồng nghiệp đã giúp tôi hoàn thành báo cáo đúng hạn."},{"en":"She gets along well with her new colleagues.","vi":"Cô ấy hòa hợp với các đồng nghiệp mới."}]', '[{"phrase":"work colleague"},{"phrase":"former colleague"},{"phrase":"colleagues at work"}]', NULL, '/ˈkɑːliːɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colle/colleague__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 12, 'bag', 'túi, bao; cặp', 'noun', '[{"en":"Don''t forget to bring a bag when you go shopping.","vi":"Đừng quên mang theo túi khi đi mua sắm."},{"en":"She put her laptop in her bag and left for work.","vi":"Cô ấy cho máy tính xách tay vào túi rồi đi làm."},{"en":"Our bags didn''t arrive, so we waited at the airport.","vi":"Hành lý của chúng tôi không đến nên chúng tôi phải đợi ở sân bay."}]', '[{"phrase":"plastic bag"},{"phrase":"shopping bag"},{"phrase":"pack your bags"},{"phrase":"school bag"}]', NULL, '/bæɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bag/bag__/bag__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 13, 'repeat', 'lặp lại; nhắc lại', 'verb', '[{"en":"Sorry, could you repeat the question, please?","vi":"Xin lỗi, bạn có thể nhắc lại câu hỏi được không?"},{"en":"Listen carefully and repeat each word after me.","vi":"Hãy nghe kỹ và lặp lại từng từ theo tôi."},{"en":"We don''t want to repeat the same mistakes as last year.","vi":"Chúng tôi không muốn lặp lại những sai lầm như năm ngoái."}]', '[{"phrase":"repeat the question"},{"phrase":"repeat after me"},{"phrase":"repeat a mistake"}]', NULL, '/rɪˈpiːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repea/repeat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 14, 'equal', 'bằng nhau; ngang hàng, bình đẳng', 'adjective', '[{"en":"Cut the cake into eight equal pieces.","vi":"Cắt bánh thành tám miếng bằng nhau."},{"en":"Men and women should get equal pay for the same work.","vi":"Nam và nữ nên được trả lương ngang nhau cho cùng một công việc."},{"en":"All students have an equal chance to win the prize.","vi":"Tất cả học sinh đều có cơ hội giành giải như nhau."}]', '[{"phrase":"equal pay"},{"phrase":"equal rights"},{"phrase":"equal chance"},{"phrase":"equal to"}]', 'be equal to something', '/ˈiːkwəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equal/equal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 15, 'expression', 'vẻ mặt, nét mặt; thành ngữ, cách diễn đạt; sự biểu lộ', 'noun', '[{"en":"I could tell from her expression that she was worried.","vi":"Nhìn vẻ mặt cô ấy, tôi biết cô ấy đang lo lắng."},{"en":"What does the expression \"break the ice\" mean?","vi":"Thành ngữ \"break the ice\" có nghĩa là gì?"},{"en":"He sent her flowers as an expression of thanks.","vi":"Anh ấy gửi hoa cho cô ấy để bày tỏ lòng biết ơn."}]', '[{"phrase":"facial expression"},{"phrase":"the expression on someone''s face"},{"phrase":"common expression"},{"phrase":"freedom of expression"}]', NULL, '/ɪkˈspreʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expre/expression__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 16, 'plus', 'cộng; cộng thêm, thêm vào đó', 'preposition', '[{"en":"Can you tell me what fifteen plus twenty-seven is?","vi":"Bạn có thể cho tôi biết mười lăm cộng hai mươi bảy bằng bao nhiêu không?"},{"en":"The room costs fifty dollars a night, plus tax.","vi":"Phòng giá năm mươi đô la một đêm, cộng thêm thuế."},{"en":"You''ll need your passport plus two recent photos.","vi":"Bạn sẽ cần hộ chiếu cùng với hai ảnh chụp gần đây."}]', '[{"phrase":"plus tax"},{"phrase":"plus or minus"},{"phrase":"a big plus"}]', NULL, '/plʌs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/plu/plus_/plus__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 17, 'extremely', 'cực kỳ, vô cùng', 'adverb', '[{"en":"The exam was extremely difficult, but I think I passed.","vi":"Bài thi cực kỳ khó, nhưng tôi nghĩ mình đã đỗ."},{"en":"We are extremely grateful for all your help.","vi":"Chúng tôi vô cùng biết ơn mọi sự giúp đỡ của bạn."},{"en":"It gets extremely hot here in the summer.","vi":"Ở đây vào mùa hè trời cực kỳ nóng."}]', '[{"phrase":"extremely difficult"},{"phrase":"extremely important"},{"phrase":"extremely grateful"},{"phrase":"extremely well"}]', NULL, '/ɪkˈstriːmli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/extre/extremely__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 18, 'owner', 'chủ, người sở hữu', 'noun', '[{"en":"The owner of the restaurant came to our table to say hello.","vi":"Chủ nhà hàng đến bàn chúng tôi để chào hỏi."},{"en":"Dog owners must keep their pets on a leash in the park.","vi":"Chủ chó phải xích thú cưng của mình khi ở trong công viên."},{"en":"Police are trying to find the owner of the car.","vi":"Cảnh sát đang cố tìm chủ của chiếc xe."}]', '[{"phrase":"the owner of"},{"phrase":"business owner"},{"phrase":"property owner"},{"phrase":"dog owner"}]', NULL, '/ˈəʊnər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/own/owner/owner__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 19, 'plane', 'máy bay', 'noun', '[{"en":"Our plane was delayed for two hours because of the weather.","vi":"Máy bay của chúng tôi bị hoãn hai tiếng vì thời tiết."},{"en":"It''s much faster to travel there by plane.","vi":"Đi đến đó bằng máy bay nhanh hơn nhiều."},{"en":"I always try to sleep on long plane journeys.","vi":"Tôi luôn cố ngủ trên những chuyến bay dài."}]', '[{"phrase":"by plane"},{"phrase":"catch a plane"},{"phrase":"get on a plane"},{"phrase":"plane ticket"}]', NULL, '/pleɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/plane/plane__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 20, 'commercial', 'thương mại; mang tính thương mại', 'adjective', '[{"en":"This area has many shops, offices and other commercial buildings.","vi":"Khu vực này có nhiều cửa hàng, văn phòng và các tòa nhà thương mại khác."},{"en":"The film was a big commercial success.","vi":"Bộ phim đã thành công lớn về mặt thương mại."},{"en":"He has worked as a commercial pilot for ten years.","vi":"Anh ấy đã làm phi công hàng không dân dụng được mười năm."}]', '[{"phrase":"commercial success"},{"phrase":"commercial building"},{"phrase":"commercial use"}]', 'Danh từ: commercial = quảng cáo trên TV/radio', '/kəˈmɜːrʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comme/commercial__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 21, 'lady', 'quý bà, người phụ nữ; phu nhân', 'noun', '[{"en":"An old lady asked me for directions to the station.","vi":"Một bà cụ hỏi tôi đường đến nhà ga."},{"en":"Good evening, ladies and gentlemen, and welcome to the show.","vi":"Chào buổi tối quý bà và quý ông, chào mừng đến với chương trình."},{"en":"The lady at the front desk gave us our room keys.","vi":"Người phụ nữ ở quầy lễ tân đưa chìa khóa phòng cho chúng tôi."}]', '[{"phrase":"old lady"},{"phrase":"young lady"},{"phrase":"ladies and gentlemen"}]', 'Số nhiều: ladies', '/ˈleɪdi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lad/lady_/lady__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 22, 'duty', 'bổn phận, nghĩa vụ; nhiệm vụ; thuế', 'noun', '[{"en":"I feel it''s my duty to take care of my parents.","vi":"Tôi cảm thấy chăm sóc bố mẹ là bổn phận của mình."},{"en":"Which doctor is on duty at the hospital tonight?","vi":"Tối nay bác sĩ nào trực ở bệnh viện?"},{"en":"Her duties include answering the phone and booking meetings.","vi":"Nhiệm vụ của cô ấy gồm nghe điện thoại và sắp xếp lịch họp."}]', '[{"phrase":"on duty"},{"phrase":"off duty"},{"phrase":"sense of duty"},{"phrase":"duty to do something"}]', NULL, '/ˈduːti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dut/duty_/duty__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 23, 'strength', 'sức mạnh, sức lực; điểm mạnh', 'noun', '[{"en":"He didn''t have the strength to lift the heavy box.","vi":"Anh ấy không đủ sức nhấc cái hộp nặng đó."},{"en":"Swimming is a good way to build strength.","vi":"Bơi lội là một cách tốt để tăng cường sức lực."},{"en":"What do you think are your main strengths and weaknesses?","vi":"Bạn nghĩ điểm mạnh và điểm yếu chính của mình là gì?"}]', '[{"phrase":"strengths and weaknesses"},{"phrase":"build strength"},{"phrase":"physical strength"},{"phrase":"inner strength"}]', 'strong (adj) – strength (n)', '/streŋkθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stren/strength__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 24, 'connect', 'kết nối; nối, liên kết', 'verb', '[{"en":"I can''t connect to the internet in my room.","vi":"Tôi không kết nối được internet trong phòng."},{"en":"A long bridge connects the island to the mainland.","vi":"Một cây cầu dài nối hòn đảo với đất liền."},{"en":"Social media helps people connect with old friends.","vi":"Mạng xã hội giúp mọi người kết nối với bạn cũ."}]', '[{"phrase":"connect to the internet"},{"phrase":"connect with"},{"phrase":"connect A to B"},{"phrase":"well connected"}]', 'connect to / with', '/kəˈnekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconn/xconnect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 25, 'cultural', '(thuộc) văn hóa', 'adjective', '[{"en":"The city has a rich cultural life with many museums and theaters.","vi":"Thành phố có đời sống văn hóa phong phú với nhiều bảo tàng và nhà hát."},{"en":"Living abroad taught me a lot about cultural differences.","vi":"Sống ở nước ngoài đã dạy tôi nhiều điều về sự khác biệt văn hóa."},{"en":"The festival is an important part of our cultural heritage.","vi":"Lễ hội là một phần quan trọng trong di sản văn hóa của chúng tôi."}]', '[{"phrase":"cultural differences"},{"phrase":"cultural heritage"},{"phrase":"cultural events"},{"phrase":"cultural identity"}]', 'culture (n) – cultural (adj)', '/ˈkʌltʃərəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cul/cultu/cultural__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 26, 'arrange', 'sắp xếp; thu xếp, bố trí', 'verb', '[{"en":"I''ve arranged a meeting with the manager for Friday.","vi":"Tôi đã sắp xếp một cuộc họp với quản lý vào thứ Sáu."},{"en":"She arranged the books on the shelf by color.","vi":"Cô ấy xếp sách trên kệ theo màu sắc."},{"en":"Can you arrange for someone to pick us up from the airport?","vi":"Bạn có thể thu xếp người đón chúng tôi ở sân bay không?"}]', '[{"phrase":"arrange a meeting"},{"phrase":"arrange for someone to do something"},{"phrase":"arrange flowers"}]', 'arrange (v) – arrangement (n)', '/əˈreɪndʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arr/arran/arrange__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 27, 'scheme', 'kế hoạch, chương trình; mưu đồ', 'noun', '[{"en":"The company has a scheme to help staff buy bikes.","vi":"Công ty có chương trình hỗ trợ nhân viên mua xe đạp."},{"en":"Over two thousand students joined the new training scheme.","vi":"Hơn hai nghìn sinh viên đã tham gia chương trình đào tạo mới."},{"en":"He lost all his savings in a scheme to get rich quickly.","vi":"Anh ấy mất hết tiền tiết kiệm vào một mưu đồ làm giàu nhanh."}]', '[{"phrase":"training scheme"},{"phrase":"pension scheme"},{"phrase":"set up a scheme"},{"phrase":"get-rich-quick scheme"}]', 'Anh: scheme = chương trình (trung tính); Mỹ: thường mang nghĩa mưu đồ', '/skiːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sch/schem/scheme__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 28, 'payment', 'sự thanh toán; khoản tiền trả', 'noun', '[{"en":"We accept payment by card or cash.","vi":"Chúng tôi chấp nhận thanh toán bằng thẻ hoặc tiền mặt."},{"en":"I forgot to make the payment for my phone bill.","vi":"Tôi quên thanh toán hóa đơn điện thoại."},{"en":"They pay for the car in monthly payments of two hundred dollars.","vi":"Họ trả tiền mua xe theo từng khoản hàng tháng hai trăm đô la."}]', '[{"phrase":"make a payment"},{"phrase":"monthly payment"},{"phrase":"late payment"},{"phrase":"payment by card"}]', 'pay (v) – payment (n)', '/ˈpeɪmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pay/payme/payment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 29, 'unfortunately', 'thật không may, đáng tiếc là', 'adverb', '[{"en":"Unfortunately, the tickets had all been sold by the time we arrived.","vi":"Thật không may, lúc chúng tôi đến thì vé đã bán hết."},{"en":"I''d love to come, but unfortunately I have to work that day.","vi":"Tôi rất muốn đến, nhưng tiếc là hôm đó tôi phải làm việc."},{"en":"Unfortunately, it rained for most of our vacation.","vi":"Thật không may, trời mưa gần suốt kỳ nghỉ của chúng tôi."}]', '[{"phrase":"but unfortunately"},{"phrase":"unfortunately for"}]', NULL, '/ʌnˈfɔːrtʃənətli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unf/unfor/unfortunately__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-09', 30, 'brief', 'ngắn gọn; ngắn, trong thời gian ngắn', 'adjective', '[{"en":"Please keep your answers brief because we don''t have much time.","vi":"Hãy trả lời ngắn gọn vì chúng ta không có nhiều thời gian."},{"en":"She gave a brief description of the new project.","vi":"Cô ấy mô tả ngắn gọn về dự án mới."},{"en":"After a brief stop in the town, we drove on to the coast.","vi":"Sau một chặng dừng ngắn ở thị trấn, chúng tôi lái xe tiếp ra bờ biển."}]', '[{"phrase":"brief description"},{"phrase":"brief visit"},{"phrase":"keep it brief"},{"phrase":"in brief"}]', NULL, '/briːf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bri/brief/brief__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-10', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 10', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 10);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 1, 'bird', 'chim', 'noun', '[{"en":"We could hear the birds singing outside our window.","vi":"Chúng tôi có thể nghe tiếng chim hót ngoài cửa sổ."},{"en":"A small bird built a nest in our garden.","vi":"Một chú chim nhỏ đã làm tổ trong vườn nhà chúng tôi."},{"en":"My grandfather feeds the birds in the park every morning.","vi":"Ông tôi cho chim ăn ở công viên mỗi sáng."}]', '[{"phrase":"wild birds"},{"phrase":"feed the birds"},{"phrase":"birds sing"},{"phrase":"a flock of birds"}]', NULL, '/bɜːrd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bir/bird_/bird__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 2, 'demonstrate', 'cho thấy, chứng minh; làm mẫu', 'verb', '[{"en":"The results clearly demonstrate that the new method works.","vi":"Kết quả cho thấy rõ phương pháp mới có hiệu quả."},{"en":"She demonstrated her skills during her first week at work.","vi":"Cô ấy đã chứng minh năng lực của mình ngay trong tuần làm việc đầu tiên."},{"en":"The chef demonstrated how to make fresh pasta at home.","vi":"Đầu bếp làm mẫu cách làm mì Ý tươi tại nhà."}]', '[{"phrase":"clearly demonstrate"},{"phrase":"demonstrate how to"},{"phrase":"demonstrate the importance of"}]', NULL, '/ˈdemənstreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dem/demon/demonstrate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 3, 'contribution', 'sự đóng góp; khoản đóng góp', 'noun', '[{"en":"Thank you for your contribution to the project.","vi":"Cảm ơn bạn vì những đóng góp cho dự án."},{"en":"Everyone made an important contribution to the team''s success.","vi":"Mỗi người đều có đóng góp quan trọng vào thành công của cả đội."},{"en":"We made a small contribution to the school''s library fund.","vi":"Chúng tôi đã góp một khoản nhỏ vào quỹ thư viện của trường."}]', '[{"phrase":"make a contribution"},{"phrase":"important contribution"},{"phrase":"contribution to"},{"phrase":"financial contribution"}]', NULL, '/ˌkɑːntrɪˈbjuːʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontribution__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 4, 'appreciate', 'cảm kích; trân trọng; hiểu rõ', 'verb', '[{"en":"I''d really appreciate it if you could call me back.","vi":"Tôi sẽ rất cảm kích nếu bạn có thể gọi lại cho tôi."},{"en":"You learn to appreciate simple things when you travel.","vi":"Khi đi du lịch, bạn học được cách trân trọng những điều giản dị."},{"en":"I don''t think you appreciate how serious this problem is.","vi":"Tôi nghĩ bạn chưa hiểu rõ vấn đề này nghiêm trọng đến mức nào."}]', '[{"phrase":"really appreciate"},{"phrase":"appreciate it"},{"phrase":"appreciate your help"},{"phrase":"greatly appreciate"}]', NULL, '/əˈpriːʃieɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appre/appreciate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 5, 'chapter', 'chương; giai đoạn', 'noun', '[{"en":"I read one chapter of my book every night.","vi":"Mỗi tối tôi đọc một chương sách."},{"en":"The first chapter was a bit slow, but it gets better.","vi":"Chương đầu hơi chậm, nhưng càng về sau càng hay."},{"en":"Moving abroad was the start of a new chapter in her life.","vi":"Chuyển ra nước ngoài là khởi đầu một giai đoạn mới trong cuộc đời cô ấy."}]', '[{"phrase":"first chapter"},{"phrase":"final chapter"},{"phrase":"a new chapter"},{"phrase":"read a chapter"}]', NULL, '/ˈtʃæptər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chapt/chapter__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 6, 'secret', 'bí mật; bí quyết', 'noun', '[{"en":"Can you keep a secret if I tell you something?","vi":"Nếu mình kể cho bạn một chuyện, bạn giữ bí mật được không?"},{"en":"She finally told her sister the secret she had kept for years.","vi":"Cuối cùng cô ấy đã kể với chị gái bí mật mà cô giữ suốt nhiều năm."},{"en":"What''s the secret to your delicious chicken soup?","vi":"Bí quyết nấu món súp gà ngon của bạn là gì?"}]', '[{"phrase":"keep a secret"},{"phrase":"tell a secret"},{"phrase":"the secret to"},{"phrase":"an open secret"}]', NULL, '/ˈsiːkrət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secre/secret__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 7, 'apparently', 'nghe nói; hình như', 'adverb', '[{"en":"Apparently, the meeting has been moved to next Tuesday.","vi":"Nghe nói cuộc họp đã được dời sang thứ Ba tuần sau."},{"en":"She was apparently unaware of the problem until yesterday.","vi":"Hình như cô ấy không hề biết về vấn đề này cho đến hôm qua."},{"en":"Apparently it''s going to rain all weekend.","vi":"Nghe nói trời sẽ mưa suốt cuối tuần."}]', '[{"phrase":"apparently unaware"},{"phrase":"apparently so"},{"phrase":"apparently not"}]', NULL, '/əˈpærəntli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appar/apparently__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 8, 'novel', 'tiểu thuyết', 'noun', '[{"en":"She is writing her first novel about growing up in a small town.","vi":"Cô ấy đang viết cuốn tiểu thuyết đầu tay về tuổi thơ ở một thị trấn nhỏ."},{"en":"I stayed up all night to finish that novel.","vi":"Tôi thức cả đêm để đọc xong cuốn tiểu thuyết đó."},{"en":"His latest novel has been made into a movie.","vi":"Cuốn tiểu thuyết mới nhất của anh ấy đã được chuyển thể thành phim."}]', '[{"phrase":"write a novel"},{"phrase":"first novel"},{"phrase":"latest novel"},{"phrase":"read a novel"}]', NULL, '/ˈnɑːvl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nov/novel/novel__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 9, 'union', 'công đoàn; hội', 'noun', '[{"en":"She joined the union when she started working at the factory.","vi":"Cô ấy gia nhập công đoàn khi bắt đầu làm việc ở nhà máy."},{"en":"The union is asking for better pay for nurses.","vi":"Công đoàn đang đòi mức lương tốt hơn cho các y tá."},{"en":"The student union organizes events for new students every year.","vi":"Hội sinh viên tổ chức các sự kiện cho tân sinh viên mỗi năm."}]', '[{"phrase":"trade union"},{"phrase":"join a union"},{"phrase":"union members"},{"phrase":"student union"}]', NULL, '/ˈjuːniən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/union/union__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 10, 'burn', 'đốt; làm cháy; làm bỏng', 'verb', '[{"en":"Be careful not to burn your hand on the stove.","vi":"Cẩn thận kẻo bị bếp làm bỏng tay nhé."},{"en":"I burned the toast again this morning.","vi":"Sáng nay tôi lại làm cháy bánh mì nướng."},{"en":"They burned the dead leaves in the backyard.","vi":"Họ đốt đống lá khô ở sân sau."}]', '[{"phrase":"burn your hand"},{"phrase":"burn down"},{"phrase":"burn calories"},{"phrase":"badly burned"}]', 'burn – burned/burnt – burned/burnt', '/bɜːrn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bur/burn_/burn__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 11, 'trend', 'xu hướng', 'noun', '[{"en":"There is a growing trend toward working from home.","vi":"Xu hướng làm việc tại nhà đang ngày càng phổ biến."},{"en":"My daughter always follows the latest fashion trends.","vi":"Con gái tôi luôn chạy theo những xu hướng thời trang mới nhất."},{"en":"Prices have shown an upward trend over the past year.","vi":"Giá cả đã cho thấy xu hướng tăng trong suốt năm qua."}]', '[{"phrase":"growing trend"},{"phrase":"latest trend"},{"phrase":"fashion trend"},{"phrase":"upward trend"}]', NULL, '/trend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tre/trend/trend__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 12, 'initial', 'ban đầu; đầu tiên', 'adjective', '[{"en":"My initial reaction was surprise, but then I felt happy.","vi":"Phản ứng ban đầu của tôi là ngạc nhiên, nhưng sau đó tôi thấy vui."},{"en":"The initial plan was to leave at six in the morning.","vi":"Kế hoạch ban đầu là khởi hành lúc sáu giờ sáng."},{"en":"After some initial problems, the new system is working well.","vi":"Sau vài trục trặc ban đầu, hệ thống mới đang hoạt động tốt."}]', '[{"phrase":"initial reaction"},{"phrase":"initial stages"},{"phrase":"initial plan"}]', NULL, '/ɪˈnɪʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ini/initi/initial__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 13, 'pleasure', 'niềm vui; sự thích thú', 'noun', '[{"en":"It was a real pleasure meeting you last night.","vi":"Được gặp bạn tối qua thật sự là một niềm vui."},{"en":"Reading in the garden is one of my greatest pleasures.","vi":"Đọc sách trong vườn là một trong những niềm vui lớn nhất của tôi."},{"en":"Are you traveling for business or for pleasure?","vi":"Bạn đi công tác hay đi chơi?"}]', '[{"phrase":"great pleasure"},{"phrase":"for pleasure"},{"phrase":"take pleasure in"},{"phrase":"my pleasure"}]', NULL, '/ˈpleʒər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/ple/pleas/pleasure__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 14, 'suggestion', 'gợi ý; đề xuất', 'noun', '[{"en":"Do you have any suggestions for a good restaurant nearby?","vi":"Bạn có gợi ý nhà hàng nào ngon gần đây không?"},{"en":"My manager accepted my suggestion to start work earlier.","vi":"Quản lý đã chấp nhận đề xuất bắt đầu làm việc sớm hơn của tôi."},{"en":"At my friend''s suggestion, I started going to bed earlier.","vi":"Theo gợi ý của bạn tôi, tôi bắt đầu đi ngủ sớm hơn."}]', '[{"phrase":"make a suggestion"},{"phrase":"accept a suggestion"},{"phrase":"helpful suggestion"}]', NULL, '/səˈdʒestʃən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sug/sugge/suggestion__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 15, 'critical', 'cực kỳ quan trọng; chỉ trích', 'adjective', '[{"en":"Getting enough sleep is critical for your health.","vi":"Ngủ đủ giấc cực kỳ quan trọng đối với sức khỏe của bạn."},{"en":"His parents were very critical of his decision to quit school.","vi":"Bố mẹ anh ấy đã chỉ trích nặng nề quyết định bỏ học của anh."},{"en":"This is a critical moment for our company.","vi":"Đây là thời điểm then chốt đối với công ty chúng tôi."}]', '[{"phrase":"critical of"},{"phrase":"critical moment"},{"phrase":"critical role"},{"phrase":"highly critical"}]', NULL, '/ˈkrɪtɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cri/criti/critical__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 16, 'gather', 'tụ tập, tập hợp; thu thập', 'verb', '[{"en":"The whole family gathers at my grandmother''s house every New Year.","vi":"Cả gia đình tụ họp ở nhà bà tôi mỗi dịp năm mới."},{"en":"A crowd gathered to watch the street musicians.","vi":"Một đám đông tụ tập để xem các nghệ sĩ đường phố biểu diễn."},{"en":"We need to gather more information before we decide.","vi":"Chúng ta cần thu thập thêm thông tin trước khi quyết định."}]', '[{"phrase":"gather information"},{"phrase":"gather together"},{"phrase":"a crowd gathered"},{"phrase":"gather data"}]', NULL, '/ˈɡæðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gat/gathe/gather__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 17, 'mostly', 'chủ yếu; phần lớn', 'adverb', '[{"en":"The audience was mostly young people and students.","vi":"Khán giả chủ yếu là người trẻ và sinh viên."},{"en":"I mostly work from home these days.","vi":"Dạo này tôi chủ yếu làm việc ở nhà."},{"en":"The weather will be mostly sunny this weekend.","vi":"Cuối tuần này trời sẽ nắng là chủ yếu."}]', '[{"phrase":"mostly sunny"},{"phrase":"mostly because"}]', NULL, '/ˈməʊstli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mos/mostl/mostly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 18, 'earth', 'trái đất; đất', 'noun', '[{"en":"The earth moves around the sun once a year.","vi":"Trái đất quay quanh mặt trời mỗi năm một vòng."},{"en":"Water covers most of the earth''s surface.","vi":"Nước bao phủ phần lớn bề mặt trái đất."},{"en":"Plant the seeds and cover them with a little earth.","vi":"Gieo hạt rồi phủ lên một ít đất."}]', '[{"phrase":"the earth''s surface"},{"phrase":"life on earth"},{"phrase":"on earth"}]', NULL, '/ɜːrθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ear/earth/earth__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 19, 'pop', 'ghé qua; nổ bốp; chợt nảy ra', 'verb', '[{"en":"I''ll pop into the store on my way home.","vi":"Trên đường về tôi sẽ ghé qua cửa hàng."},{"en":"The balloon popped and scared the baby.","vi":"Quả bóng bay nổ bốp làm em bé giật mình."},{"en":"A funny idea suddenly popped into my head.","vi":"Một ý tưởng buồn cười chợt nảy ra trong đầu tôi."}]', '[{"phrase":"pop into"},{"phrase":"pop in"},{"phrase":"pop out"},{"phrase":"pop into your head"}]', 'pop – popped – popped', '/pɑːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pop/pop__/pop__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 20, 'essential', 'thiết yếu; rất cần thiết', 'adjective', '[{"en":"Water is essential for all living things.","vi":"Nước rất cần thiết cho mọi sinh vật sống."},{"en":"A good map is essential when you hike in the mountains.","vi":"Một tấm bản đồ tốt là thứ thiết yếu khi bạn leo núi."},{"en":"It''s essential to book early during the holiday season.","vi":"Đặt chỗ sớm vào mùa lễ là điều rất cần thiết."}]', '[{"phrase":"essential for"},{"phrase":"absolutely essential"},{"phrase":"essential part of"}]', NULL, '/ɪˈsenʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ess/essen/essential__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 21, 'desire', 'mong muốn; khao khát', 'noun', '[{"en":"She has a strong desire to study abroad.","vi":"Cô ấy có mong muốn mãnh liệt được đi du học."},{"en":"He had no desire to go back to his old job.","vi":"Anh ấy không hề muốn quay lại công việc cũ."},{"en":"Many young people share a desire for more freedom.","vi":"Nhiều người trẻ có chung khao khát được tự do hơn."}]', '[{"phrase":"strong desire"},{"phrase":"no desire"},{"phrase":"desire to"},{"phrase":"desire for"}]', NULL, '/dɪˈzaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/desir/desire__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 22, 'promote', 'thăng chức; quảng bá; thúc đẩy', 'verb', '[{"en":"She was promoted to manager after only two years.","vi":"Cô ấy được thăng chức lên quản lý chỉ sau hai năm."},{"en":"The band is touring to promote their new album.","vi":"Ban nhạc đang đi lưu diễn để quảng bá album mới."},{"en":"The city wants to promote the use of public transportation.","vi":"Thành phố muốn thúc đẩy việc sử dụng phương tiện giao thông công cộng."}]', '[{"phrase":"be promoted to"},{"phrase":"promote a product"},{"phrase":"promote the use of"}]', NULL, '/prəˈməʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/promo/promote__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 23, 'currently', 'hiện nay; hiện tại', 'adverb', '[{"en":"I''m currently looking for a new apartment.","vi":"Hiện tôi đang tìm một căn hộ mới."},{"en":"The museum is currently closed for repairs.","vi":"Bảo tàng hiện đang đóng cửa để sửa chữa."},{"en":"How many people currently work at your company?","vi":"Hiện có bao nhiêu người làm việc ở công ty bạn?"}]', '[{"phrase":"currently available"},{"phrase":"currently working on"},{"phrase":"currently looking for"}]', NULL, '/ˈkɜːrəntli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cur/curre/currently__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 24, 'employ', 'thuê, tuyển dụng; sử dụng', 'verb', '[{"en":"The factory employs more than five hundred workers.","vi":"Nhà máy thuê hơn năm trăm công nhân."},{"en":"She has been employed as a nurse for ten years.","vi":"Cô ấy được tuyển dụng làm y tá đã mười năm nay."},{"en":"Teachers employ different methods to keep students interested.","vi":"Giáo viên sử dụng nhiều phương pháp khác nhau để giữ cho học sinh hứng thú."}]', '[{"phrase":"employ workers"},{"phrase":"be employed as"},{"phrase":"employ a method"}]', NULL, '/ɪmˈplɔɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/emplo/employ__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 25, 'path', 'lối đi; con đường', 'noun', '[{"en":"We walked along a narrow path through the forest.","vi":"Chúng tôi đi dọc theo một lối mòn hẹp xuyên qua khu rừng."},{"en":"A fallen tree was blocking the path.","vi":"Một cái cây đổ đang chắn lối đi."},{"en":"He chose a different career path from his parents.","vi":"Anh ấy chọn một con đường sự nghiệp khác với bố mẹ."}]', '[{"phrase":"narrow path"},{"phrase":"career path"},{"phrase":"block the path"},{"phrase":"follow a path"}]', NULL, '/pæθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pat/path_/path__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 26, 'topic', 'chủ đề', 'noun', '[{"en":"Let''s change the topic and talk about something fun.","vi":"Chúng ta đổi chủ đề và nói chuyện gì đó vui đi."},{"en":"The teacher asked us to choose a topic for our essays.","vi":"Giáo viên yêu cầu chúng tôi chọn một chủ đề cho bài luận."},{"en":"Money is a sensitive topic in many families.","vi":"Tiền bạc là chủ đề nhạy cảm trong nhiều gia đình."}]', '[{"phrase":"change the topic"},{"phrase":"choose a topic"},{"phrase":"sensitive topic"},{"phrase":"topic of conversation"}]', NULL, '/ˈtɑːpɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/top/topic/topic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 27, 'beach', 'bãi biển', 'noun', '[{"en":"We spent the whole afternoon lying on the beach.","vi":"Chúng tôi dành cả buổi chiều nằm trên bãi biển."},{"en":"The hotel is only a five-minute walk from the beach.","vi":"Khách sạn chỉ cách bãi biển năm phút đi bộ."},{"en":"Let''s go to the beach if the weather is nice tomorrow.","vi":"Nếu mai trời đẹp thì mình đi biển nhé."}]', '[{"phrase":"on the beach"},{"phrase":"go to the beach"},{"phrase":"sandy beach"},{"phrase":"beach house"}]', NULL, '/biːtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bea/beach/beach__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 28, 'attract', 'thu hút; hấp dẫn', 'verb', '[{"en":"The festival attracts thousands of visitors every summer.","vi":"Lễ hội thu hút hàng nghìn du khách mỗi mùa hè."},{"en":"Bright colors attract bees and butterflies to the flowers.","vi":"Màu sắc rực rỡ thu hút ong và bướm đến với những bông hoa."},{"en":"The company offers higher pay to attract new staff.","vi":"Công ty trả lương cao hơn để thu hút nhân viên mới."}]', '[{"phrase":"attract visitors"},{"phrase":"attract attention"},{"phrase":"attract customers"},{"phrase":"be attracted to"}]', NULL, '/əˈtrækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attra/attract__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 29, 'engage', 'tham gia; thu hút, lôi cuốn', 'verb', '[{"en":"Students who engage in class discussions usually learn faster.","vi":"Những học sinh tham gia thảo luận trong lớp thường học nhanh hơn."},{"en":"The teacher uses games to engage young learners.","vi":"Giáo viên dùng trò chơi để lôi cuốn học sinh nhỏ tuổi."},{"en":"Many retired people engage in volunteer work.","vi":"Nhiều người đã nghỉ hưu tham gia công việc tình nguyện."}]', '[{"phrase":"engage in"},{"phrase":"engage with"},{"phrase":"engage students"},{"phrase":"fully engage"}]', 'engage in sth: tham gia vào việc gì', '/ɪnˈɡeɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eng/engag/engage__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-10', 30, 'powerful', 'mạnh mẽ; có quyền lực', 'adjective', '[{"en":"This new laptop is small but very powerful.","vi":"Chiếc laptop mới này nhỏ nhưng rất mạnh."},{"en":"She gave a powerful speech at the graduation ceremony.","vi":"Cô ấy đã có một bài phát biểu đầy sức lay động tại lễ tốt nghiệp."},{"en":"He comes from a rich and powerful family.","vi":"Anh ấy xuất thân từ một gia đình giàu có và quyền lực."}]', '[{"phrase":"rich and powerful"},{"phrase":"very powerful"},{"phrase":"powerful speech"}]', NULL, '/ˈpaʊərfl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pow/power/powerful__us_3.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-11', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 11', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 11);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 1, 'flower', 'hoa; bông hoa', 'noun', '[{"en":"She bought a bunch of flowers for her mother''s birthday.","vi":"Cô ấy mua một bó hoa tặng sinh nhật mẹ."},{"en":"The flowers in our garden bloom every spring.","vi":"Những bông hoa trong vườn nhà chúng tôi nở vào mỗi mùa xuân."},{"en":"Please don''t pick the flowers in the park.","vi":"Xin đừng hái hoa trong công viên."}]', '[{"phrase":"bunch of flowers"},{"phrase":"pick flowers"},{"phrase":"fresh flowers"},{"phrase":"flower shop"}]', NULL, '/ˈflaʊər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/flo/flowe/flower__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 2, 'crisis', 'khủng hoảng', 'noun', '[{"en":"The company is facing a serious financial crisis this year.","vi":"Năm nay công ty đang đối mặt với một cuộc khủng hoảng tài chính nghiêm trọng."},{"en":"Many families lost their homes during the economic crisis.","vi":"Nhiều gia đình đã mất nhà trong cuộc khủng hoảng kinh tế."},{"en":"She always stays calm and thinks clearly in a crisis.","vi":"Cô ấy luôn giữ bình tĩnh và suy nghĩ sáng suốt khi gặp khủng hoảng."}]', '[{"phrase":"financial crisis"},{"phrase":"economic crisis"},{"phrase":"face a crisis"},{"phrase":"in a crisis"}]', 'số nhiều: crises', '/ˈkraɪsɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cri/crisi/crisis__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 3, 'settle', 'giải quyết; định cư; ổn định', 'verb', '[{"en":"They finally settled the argument after a long talk.","vi":"Cuối cùng họ đã giải quyết được cuộc tranh cãi sau một buổi nói chuyện dài."},{"en":"My grandparents settled in this town fifty years ago.","vi":"Ông bà tôi đã định cư ở thị trấn này từ năm mươi năm trước."},{"en":"It took the kids a few weeks to settle into their new school.","vi":"Bọn trẻ mất vài tuần để ổn định ở trường mới."}]', '[{"phrase":"settle an argument"},{"phrase":"settle a dispute"},{"phrase":"settle down"},{"phrase":"settle in"}]', NULL, '/ˈsetl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/set/settl/settle__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 4, 'boat', 'thuyền', 'noun', '[{"en":"We took a boat across the lake to the island.","vi":"Chúng tôi đi thuyền qua hồ để ra đảo."},{"en":"My uncle goes fishing in his small boat every morning.","vi":"Chú tôi đi câu cá bằng chiếc thuyền nhỏ của chú mỗi sáng."},{"en":"Have you ever been on a boat trip?","vi":"Bạn đã bao giờ đi chơi bằng thuyền chưa?"}]', '[{"phrase":"by boat"},{"phrase":"boat trip"},{"phrase":"fishing boat"}]', NULL, '/bəʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/boa/boat_/boat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 5, 'aid', 'viện trợ; sự hỗ trợ', 'noun', '[{"en":"The government sent food aid to the flooded areas.","vi":"Chính phủ đã gửi lương thực viện trợ đến các vùng bị ngập lụt."},{"en":"Many students rely on financial aid to pay for college.","vi":"Nhiều sinh viên dựa vào hỗ trợ tài chính để trả tiền học đại học."},{"en":"He can only read small print with the aid of glasses.","vi":"Anh ấy chỉ đọc được chữ nhỏ khi có kính hỗ trợ."}]', '[{"phrase":"food aid"},{"phrase":"financial aid"},{"phrase":"first aid"},{"phrase":"with the aid of"}]', NULL, '/eɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aid/aid__/aid__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 6, 'fan', 'người hâm mộ; quạt', 'noun', '[{"en":"Thousands of fans waited outside the stadium for the players.","vi":"Hàng nghìn người hâm mộ chờ các cầu thủ bên ngoài sân vận động."},{"en":"I''ve been a big fan of her music since high school.","vi":"Tôi đã rất hâm mộ âm nhạc của cô ấy từ hồi cấp ba."},{"en":"It''s so hot in here; can you turn on the fan?","vi":"Trong này nóng quá, bạn bật quạt lên được không?"}]', '[{"phrase":"big fan"},{"phrase":"football fan"},{"phrase":"turn on the fan"},{"phrase":"ceiling fan"}]', NULL, '/fæn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fan/fan__/fan__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 7, 'kitchen', 'nhà bếp', 'noun', '[{"en":"Mom is cooking dinner in the kitchen right now.","vi":"Mẹ đang nấu bữa tối trong bếp."},{"en":"We sat at the kitchen table and talked for hours.","vi":"Chúng tôi ngồi ở bàn bếp và nói chuyện hàng giờ liền."},{"en":"Their new apartment has a small but bright kitchen.","vi":"Căn hộ mới của họ có một gian bếp nhỏ nhưng sáng sủa."}]', '[{"phrase":"in the kitchen"},{"phrase":"kitchen table"},{"phrase":"kitchen sink"}]', NULL, '/ˈkɪtʃɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kit/kitch/kitchen__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 8, 'twice', 'hai lần; gấp đôi', 'adverb', '[{"en":"I go to the gym twice a week.","vi":"Tôi đến phòng tập hai lần một tuần."},{"en":"She read the letter twice before she understood it.","vi":"Cô ấy đọc lá thư hai lần rồi mới hiểu."},{"en":"Their new house is twice as big as the old one.","vi":"Ngôi nhà mới của họ rộng gấp đôi ngôi nhà cũ."}]', '[{"phrase":"twice a week"},{"phrase":"twice a day"},{"phrase":"twice as much"},{"phrase":"think twice"}]', NULL, '/twaɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/twi/twice/twice__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 9, 'fresh', 'tươi; trong lành; mới', 'adjective', '[{"en":"We buy fresh vegetables at the market every morning.","vi":"Chúng tôi mua rau tươi ở chợ mỗi sáng."},{"en":"Let''s open the window and get some fresh air.","vi":"Mình mở cửa sổ ra để đón chút không khí trong lành đi."},{"en":"After the holiday, I came back to work with fresh ideas.","vi":"Sau kỳ nghỉ, tôi quay lại làm việc với những ý tưởng mới."}]', '[{"phrase":"fresh air"},{"phrase":"fresh fruit"},{"phrase":"fresh start"}]', NULL, '/freʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fre/fresh/fresh__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 10, 'delay', 'trì hoãn; làm chậm trễ', 'verb', '[{"en":"Our flight was delayed for three hours because of the storm.","vi":"Chuyến bay của chúng tôi bị trễ ba tiếng vì bão."},{"en":"Don''t delay seeing a doctor if the pain gets worse.","vi":"Đừng chần chừ đi khám bác sĩ nếu cơn đau nặng hơn."},{"en":"Heavy traffic delayed us, so we missed the start of the movie.","vi":"Kẹt xe làm chúng tôi bị trễ nên lỡ mất đoạn đầu bộ phim."}]', '[{"phrase":"delay a decision"},{"phrase":"be delayed by"},{"phrase":"without delay"}]', NULL, '/dɪˈleɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/del/delay/delay__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 11, 'safety', 'sự an toàn', 'noun', '[{"en":"For your safety, please keep your seat belt fastened.","vi":"Vì sự an toàn của bạn, vui lòng luôn thắt dây an toàn."},{"en":"Parents always worry about their children''s safety online.","vi":"Cha mẹ luôn lo lắng về sự an toàn của con cái trên mạng."},{"en":"All workers must follow the safety rules on the construction site.","vi":"Tất cả công nhân phải tuân thủ các quy định an toàn ở công trường."}]', '[{"phrase":"safety rules"},{"phrase":"road safety"},{"phrase":"food safety"},{"phrase":"for your safety"}]', 'không đếm được', '/ˈseɪfti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/saf/safet/safety__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 12, 'engineer', 'kỹ sư', 'noun', '[{"en":"My brother works as an engineer for a car company.","vi":"Anh trai tôi làm kỹ sư cho một công ty ô tô."},{"en":"The engineers are checking the bridge for any damage.","vi":"Các kỹ sư đang kiểm tra xem cây cầu có hư hại gì không."},{"en":"She wants to become a software engineer after college.","vi":"Cô ấy muốn trở thành kỹ sư phần mềm sau khi học xong đại học."}]', '[{"phrase":"software engineer"},{"phrase":"civil engineer"},{"phrase":"work as an engineer"}]', NULL, '/ˌendʒɪˈnɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eng/engin/engineer__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 13, 'quiet', 'yên tĩnh; im lặng', 'adjective', '[{"en":"The library is a quiet place to study.","vi":"Thư viện là một nơi yên tĩnh để học bài."},{"en":"Please be quiet; the baby is sleeping.","vi":"Làm ơn giữ im lặng, em bé đang ngủ."},{"en":"We live on a quiet street far from the city center.","vi":"Chúng tôi sống trên một con phố yên tĩnh, cách xa trung tâm thành phố."}]', '[{"phrase":"be quiet"},{"phrase":"keep quiet"},{"phrase":"quiet place"},{"phrase":"quiet street"}]', 'quiet (yên tĩnh) ≠ quite (khá)', '/ˈkwaɪət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qui/quiet/quiet__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 14, 'insurance', 'bảo hiểm', 'noun', '[{"en":"Does your new job come with health insurance?","vi":"Công việc mới của bạn có kèm bảo hiểm y tế không?"},{"en":"You need car insurance before you can drive on the road.","vi":"Bạn cần có bảo hiểm xe trước khi được lái xe ra đường."},{"en":"The insurance company paid for the damage after the fire.","vi":"Công ty bảo hiểm đã chi trả cho thiệt hại sau vụ cháy."}]', '[{"phrase":"health insurance"},{"phrase":"car insurance"},{"phrase":"insurance company"},{"phrase":"travel insurance"}]', 'không đếm được', '/ɪnˈʃʊrəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insur/insurance__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 15, 'nurse', 'y tá', 'noun', '[{"en":"The nurse checked my temperature and blood pressure.","vi":"Y tá đã đo nhiệt độ và huyết áp cho tôi."},{"en":"My aunt has worked as a nurse for twenty years.","vi":"Dì tôi đã làm y tá được hai mươi năm."},{"en":"Ask the nurse if you need more water or a blanket.","vi":"Hãy hỏi y tá nếu bạn cần thêm nước hoặc chăn."}]', '[{"phrase":"work as a nurse"},{"phrase":"school nurse"},{"phrase":"night nurse"}]', NULL, '/nɜːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nur/nurse/nurse__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 16, 'divide', 'chia; phân chia', 'verb', '[{"en":"Divide the cake into eight equal pieces.","vi":"Hãy chia chiếc bánh thành tám phần bằng nhau."},{"en":"The teacher divided the class into small groups.","vi":"Giáo viên chia lớp thành các nhóm nhỏ."},{"en":"If you divide twenty by four, you get five.","vi":"Nếu lấy hai mươi chia cho bốn, bạn được năm."}]', '[{"phrase":"divide into"},{"phrase":"divide by"},{"phrase":"divide equally"}]', 'divide into (chia thành) · divide by (chia cho)', '/dɪˈvaɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/div/divid/divide__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 17, 'length', 'chiều dài; độ dài', 'noun', '[{"en":"Can you measure the length of this table for me?","vi":"Bạn đo giúp tôi chiều dài của cái bàn này được không?"},{"en":"The bridge has a total length of two kilometers.","vi":"Cây cầu có tổng chiều dài là hai ki-lô-mét."},{"en":"Your essay should be about 500 words in length.","vi":"Bài luận của bạn nên dài khoảng 500 từ."}]', '[{"phrase":"the length of"},{"phrase":"in length"},{"phrase":"total length"}]', NULL, '/leŋkθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/len/lengt/length__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 18, 'investigation', 'cuộc điều tra', 'noun', '[{"en":"The police have started an investigation into the fire.","vi":"Cảnh sát đã bắt đầu một cuộc điều tra về vụ cháy."},{"en":"The cause of the accident is still under investigation.","vi":"Nguyên nhân vụ tai nạn vẫn đang được điều tra."},{"en":"After a long investigation, they found the missing money.","vi":"Sau một cuộc điều tra dài, họ đã tìm ra số tiền bị mất."}]', '[{"phrase":"investigation into"},{"phrase":"under investigation"},{"phrase":"carry out an investigation"},{"phrase":"police investigation"}]', NULL, '/ɪnˌvestɪˈɡeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inves/investigation__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 19, 'package', 'gói hàng, bưu kiện; gói dịch vụ', 'noun', '[{"en":"A package arrived for you while you were out.","vi":"Có một bưu kiện gửi đến cho bạn lúc bạn đi vắng."},{"en":"I need to send this package to my sister in Hanoi.","vi":"Tôi cần gửi gói hàng này cho chị gái tôi ở Hà Nội."},{"en":"The hotel offers a vacation package that includes meals and tours.","vi":"Khách sạn có gói nghỉ dưỡng bao gồm các bữa ăn và chuyến tham quan."}]', '[{"phrase":"send a package"},{"phrase":"receive a package"},{"phrase":"vacation package"}]', NULL, '/ˈpækɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pac/packa/package__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 20, 'somewhere', 'ở đâu đó; nơi nào đó', 'adverb', '[{"en":"I left my keys somewhere in the house.","vi":"Tôi để quên chìa khóa ở đâu đó trong nhà."},{"en":"Let''s go somewhere quiet where we can talk.","vi":"Mình đi đâu đó yên tĩnh để có thể nói chuyện đi."},{"en":"She lives somewhere near the old train station.","vi":"Cô ấy sống ở đâu đó gần nhà ga cũ."}]', '[{"phrase":"somewhere else"},{"phrase":"somewhere near"},{"phrase":"go somewhere"}]', NULL, '/ˈsʌmwer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/somew/somewhere__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 21, 'expand', 'mở rộng; nở ra', 'verb', '[{"en":"The company plans to expand into Asian markets next year.","vi":"Công ty dự định mở rộng sang các thị trường châu Á vào năm tới."},{"en":"The restaurant expanded its menu to include vegetarian dishes.","vi":"Nhà hàng đã mở rộng thực đơn để có thêm các món chay."},{"en":"Most metals expand when they are heated.","vi":"Hầu hết kim loại nở ra khi bị nung nóng."}]', '[{"phrase":"expand rapidly"},{"phrase":"expand the business"},{"phrase":"expand into"}]', NULL, '/ɪkˈspænd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expan/expand__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 22, 'commit', 'phạm (tội, lỗi); cam kết', 'verb', '[{"en":"The police believe he committed the crime alone.","vi":"Cảnh sát tin rằng anh ta đã gây án một mình."},{"en":"We are committed to giving our customers the best service.","vi":"Chúng tôi cam kết mang đến dịch vụ tốt nhất cho khách hàng."},{"en":"Before you commit to a two-year contract, read it carefully.","vi":"Trước khi cam kết với một hợp đồng hai năm, hãy đọc kỹ nó."}]', '[{"phrase":"commit a crime"},{"phrase":"commit to"},{"phrase":"be committed to"},{"phrase":"fully committed"}]', 'commit to + V-ing: cam kết làm gì', '/kəˈmɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commi/commit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 23, 'obvious', 'rõ ràng; hiển nhiên', 'adjective', '[{"en":"It was obvious that she was nervous before the exam.","vi":"Rõ ràng là cô ấy đã lo lắng trước kỳ thi."},{"en":"The answer seems obvious now, but it wasn''t at first.","vi":"Giờ thì đáp án có vẻ hiển nhiên, nhưng lúc đầu thì không."},{"en":"For obvious reasons, we can''t talk about it in front of the kids.","vi":"Vì những lý do hiển nhiên, chúng ta không thể nói chuyện đó trước mặt bọn trẻ."}]', '[{"phrase":"it is obvious that"},{"phrase":"for obvious reasons"},{"phrase":"obvious choice"}]', NULL, '/ˈɑːbviəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obv/obvio/obvious__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 24, 'jump', 'nhảy; tăng vọt', 'verb', '[{"en":"The kids love jumping into the swimming pool.","vi":"Bọn trẻ rất thích nhảy xuống hồ bơi."},{"en":"The cat jumped onto the table and knocked over my cup.","vi":"Con mèo nhảy lên bàn và làm đổ cốc của tôi."},{"en":"Prices jumped by twenty percent in just one month.","vi":"Giá cả tăng vọt hai mươi phần trăm chỉ trong một tháng."}]', '[{"phrase":"jump into"},{"phrase":"jump over"},{"phrase":"jump up and down"}]', NULL, '/dʒʌmp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jum/jump_/jump__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 25, 'weapon', 'vũ khí', 'noun', '[{"en":"Security staff at the airport check bags for weapons.","vi":"Nhân viên an ninh sân bay kiểm tra túi xách xem có vũ khí không."},{"en":"In the past, soldiers used swords as their main weapons.","vi":"Ngày xưa, binh lính dùng kiếm làm vũ khí chính."},{"en":"Her smile is her secret weapon in job interviews.","vi":"Nụ cười là vũ khí bí mật của cô ấy trong các buổi phỏng vấn xin việc."}]', '[{"phrase":"secret weapon"},{"phrase":"carry a weapon"}]', NULL, '/ˈwepən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wea/weapo/weapon__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 26, 'relatively', 'tương đối; khá', 'adverb', '[{"en":"The exam was relatively easy compared to last year''s.","vi":"Kỳ thi tương đối dễ so với năm ngoái."},{"en":"Houses in this area are still relatively cheap.","vi":"Nhà ở khu vực này vẫn còn khá rẻ."},{"en":"She learned to drive in a relatively short time.","vi":"Cô ấy học lái xe trong một thời gian tương đối ngắn."}]', '[{"phrase":"relatively easy"},{"phrase":"relatively small"},{"phrase":"relatively cheap"},{"phrase":"relatively short"}]', NULL, '/ˈrelətɪvli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relat/relatively__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 27, 'host', 'chủ nhà; người dẫn chương trình', 'noun', '[{"en":"Our host welcomed us with tea and cakes.","vi":"Chủ nhà đón tiếp chúng tôi bằng trà và bánh."},{"en":"He is the host of a popular cooking show.","vi":"Anh ấy là người dẫn một chương trình nấu ăn được yêu thích."},{"en":"Remember to thank the host before you leave the party.","vi":"Nhớ cảm ơn chủ nhà trước khi rời bữa tiệc nhé."}]', '[{"phrase":"host family"},{"phrase":"host country"},{"phrase":"talk show host"}]', NULL, '/həʊst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hos/host_/host__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 28, 'winter', 'mùa đông', 'noun', '[{"en":"It snows a lot here during the winter months.","vi":"Ở đây tuyết rơi nhiều vào những tháng mùa đông."},{"en":"We''re planning a ski trip this winter.","vi":"Chúng tôi đang lên kế hoạch đi trượt tuyết vào mùa đông năm nay."},{"en":"Don''t forget to bring a warm winter coat.","vi":"Đừng quên mang theo một chiếc áo khoác mùa đông thật ấm."}]', '[{"phrase":"in winter"},{"phrase":"this winter"},{"phrase":"winter coat"},{"phrase":"cold winter"}]', NULL, '/ˈwɪntər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/win/winte/winter__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 29, 'district', 'quận, huyện; khu vực', 'noun', '[{"en":"My office is in District 1, not far from the river.","vi":"Văn phòng của tôi ở Quận 1, cách sông không xa."},{"en":"This is the busiest shopping district in the city.","vi":"Đây là khu mua sắm sầm uất nhất thành phố."},{"en":"Most children in this district go to the same elementary school.","vi":"Hầu hết trẻ em trong quận này học cùng một trường tiểu học."}]', '[{"phrase":"shopping district"},{"phrase":"business district"},{"phrase":"school district"}]', NULL, '/ˈdɪstrɪkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/distr/district__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-11', 30, 'broad', 'rộng; bao quát', 'adjective', '[{"en":"The river is very broad at this point.","vi":"Con sông rất rộng ở đoạn này."},{"en":"He has broad shoulders and a friendly smile.","vi":"Anh ấy có bờ vai rộng và nụ cười thân thiện."},{"en":"The course gives students a broad understanding of modern history.","vi":"Khóa học mang lại cho sinh viên hiểu biết bao quát về lịch sử hiện đại."}]', '[{"phrase":"broad shoulders"},{"phrase":"a broad range of"},{"phrase":"broad smile"}]', NULL, '/brɔːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bro/broad/broad__us_2.mp3', NULL, NULL);
